INSERT INTO "traducao" ("id", "idioma", "hash_origem", "texto") VALUES
  (gen_random_uuid()::text, 'en', 'a4079029268e4660', ', all in the middle position.'),
  (gen_random_uuid()::text, 'en', '0b1c60f0d880a91c', '26 word pairs · 3 to 5 minutes'),
  (gen_random_uuid()::text, 'en', 'b4d12aab565dedaa', '8 word pairs · 1 to 2 minutes'),
  (gen_random_uuid()::text, 'en', '3bd0b54b3c644bf9', '8, taken from the 26'),
  (gen_random_uuid()::text, 'en', '00bf7ea7a7150a2c', 'The UEQ-S Data Analysis Tool V15, already filled in with {quantidade} from version {nome} that are in the analysis. Open it in Excel and click Enable Editing: the spreadsheet recalculates by itself, with its charts, benchmark and suspicious responses.'),
  (gen_random_uuid()::text, 'en', 'f9150f74d9f74fe5', 'The UEQ-S Data Analysis Tool V15, already filled in with {quantidade} that are in the analysis. Open it in Excel and click Enable Editing: the spreadsheet recalculates by itself, with its charts, benchmark and suspicious responses.'),
  (gen_random_uuid()::text, 'en', '7a7c53d439c4bf48', 'The UEQ-S tab shows the evaluation of the short version: pragmatic, hedonic and overall quality, with its benchmark and official spreadsheet. In a UEQ-S study it is the whole dashboard; in a full UEQ study, it uses the 8 UEQ-S pairs that participants also answered.'),
  (gen_random_uuid()::text, 'en', 'f1ae8e277add0379', 'The same comparison with the official data set, in five bands, from Excellent (among the best 10%) to Bad (among the worst 25%). The official UEQ-S spreadsheet warns that there is not enough data for the short version yet: the limits come from the same 8 items within the full UEQ and are an approximation, to be read with care.'),
  (gen_random_uuid()::text, 'en', 'ce2f7def94215f23', 'The same position was marked in {iguais} of the 8 items{v}'),
  (gen_random_uuid()::text, 'en', 'a7a4e2547797b3dc', 'There is not enough data for the short version yet: the UEQ-S limits come from the same 8 items within the full UEQ. Use the bands as a first estimate.'),
  (gen_random_uuid()::text, 'en', 'ef299d5bbf1652c9', 'Approximate: the limits still come from the same 8 items within the full UEQ'),
  (gen_random_uuid()::text, 'en', 'ba3669e3ba121cc2', 'Both scales inconsistent, or the middle position ({meio}) in all 8 items'),
  (gen_random_uuid()::text, 'en', '04a4bec03d5421ad', 'The 6 scales and, from them, pragmatic and hedonic quality'),
  (gen_random_uuid()::text, 'en', 'ff1816b44eeac188', 'The means, confidence intervals, alpha and benchmark of pragmatic, hedonic and overall quality appear here as soon as the first response arrives.'),
  (gen_random_uuid()::text, 'en', '8362db625cf11792', 'Approximate benchmark.'),
  (gen_random_uuid()::text, 'en', '4ec93dc43d6943cf', 'Each dot is the mean of the responses to the pair, from the left term (-3) to the right term (+3). In the UEQ-S the negative term is always on the left.'),
  (gen_random_uuid()::text, 'en', 'd4679986e4a13fa2', 'How should I read the overall scale?'),
  (gen_random_uuid()::text, 'en', '15900c5ffe6b043b', '1 to 2 minutes'),
  (gen_random_uuid()::text, 'en', 'd84a57665a63d405', '1 to 2 minutes · voluntary and anonymous'),
  (gen_random_uuid()::text, 'en', '56deeeb5cd215073', '2 to 3 minutes · voluntary and anonymous'),
  (gen_random_uuid()::text, 'en', '6299af052f4defd9', '3 to 5 minutes'),
  (gen_random_uuid()::text, 'en', 'f426d43aed1aae02', 'After the first response the choice is locked, so the study does not mix the two questionnaires.'),
  (gen_random_uuid()::text, 'en', '2a804d05f2c8bc31', 'Differences between the full UEQ and the UEQ-S'),
  (gen_random_uuid()::text, 'en', '1c3de5d03a2c189d', 'UEQ-S scales'),
  (gen_random_uuid()::text, 'en', 'b2fdc6cdf7a4e017', 'Choose the questionnaire: full UEQ or UEQ-S.'),
  (gen_random_uuid()::text, 'en', 'b50ee17343aec113', 'UEQ-S study'),
  (gen_random_uuid()::text, 'en', '51658f25775c996d', 'Ferramenta UEQ · UEQ-S results dashboard'),
  (gen_random_uuid()::text, 'en', 'f1d3445f45dc3300', 'Overall'),
  (gen_random_uuid()::text, 'en', '3b297def8e05630a', 'Item {numero}: from {esquerdo} to {direito}'),
  (gen_random_uuid()::text, 'en', '98f022d65a10c65c', 'Items 1 to 4'),
  (gen_random_uuid()::text, 'en', 'adcce322242c323d', 'Items 5 to 8'),
  (gen_random_uuid()::text, 'en', 'dd339111f097feb6', 'Measures the 6 scales (Attractiveness, Perspicuity, Efficiency, Dependability, Stimulation and Novelty) and, from them, pragmatic and hedonic quality. It is recommended for most studies, such as after a usability test.'),
  (gen_random_uuid()::text, 'en', 'a61910ac3ff95713', 'Measures only pragmatic quality, hedonic quality and an overall score, without the 6 scales. Use it when the full version does not fit: little time, the UEQ inside a longer questionnaire, or the same person rating several products in a row.'),
  (gen_random_uuid()::text, 'en', '8597715d8249479a', 'Same format, with values from -3 to +3. In the UEQ-S the positive term is always on the right.'),
  (gen_random_uuid()::text, 'en', 'dd96696d8f635d25', 'Means of the three UEQ-S scales with 95% confidence interval and benchmark bands.'),
  (gen_random_uuid()::text, 'en', '1e255e23d55c6fae', 'In most studies, such as after a usability test'),
  (gen_random_uuid()::text, 'en', 'c0d82be82fc68e75', 'In a full UEQ study, the results also show the UEQ-S, in its own tab, calculated from its 8 pairs.'),
  (gen_random_uuid()::text, 'en', '2b516db65a9ff8e6', 'The full UEQ has 26 pairs and measures the 6 scales; it is recommended for most studies. The UEQ-S has 8 of those pairs, takes 1 to 2 minutes and measures only pragmatic quality, hedonic quality and an overall score; use it when the full version does not fit. The choice changes the questionnaire, the dashboard and the exported spreadsheet, and is locked at the first response.'),
  (gen_random_uuid()::text, 'en', 'aea48ff81a944c25', 'The UEQ comes in two forms. Both use the same pairs of opposite words and the same 7-point scale; the short version uses only 8 of the 26 pairs.'),
  (gen_random_uuid()::text, 'en', '6d0c31c3f5025db1', 'The UEQ-S from the full UEQ.'),
  (gen_random_uuid()::text, 'en', 'd37e05a5e11d0ce3', 'The UEQ-S is 8 of the 26 pairs: 11, 13, 20 and 21 (pragmatic quality) and 6, 7, 10 and 15 (hedonic quality). This tab uses the answers participants gave to those pairs, the same way the authors built the UEQ-S and its benchmark. For the 6 scales, go back to the UEQ scales tab.'),
  (gen_random_uuid()::text, 'en', '6019d611a7d470f0', 'The UEQ-S is the short version of the UEQ: 8 of the same 26 pairs, with the same 7-point scale. It is quicker to answer, but it does not separate the 6 scales. You choose one of the two when you create the study.'),
  (gen_random_uuid()::text, 'en', 'bae875592e85a23c', 'The study already has responses, so the questionnaire can no longer change. To use the other one, create a new study.'),
  (gen_random_uuid()::text, 'en', '3b30696110490a7b', 'The official one, with 21,175 people from 468 studies'),
  (gen_random_uuid()::text, 'en', 'e124308087e6e9c0', 'What it measures'),
  (gen_random_uuid()::text, 'en', '42f77b4043940783', 'What the choice changes:'),
  (gen_random_uuid()::text, 'en', '3c3472b75b92e9b3', 'What are pragmatic and hedonic quality?'),
  (gen_random_uuid()::text, 'en', '068ea3511e50f59a', 'What is the UEQ-S benchmark?'),
  (gen_random_uuid()::text, 'en', 'e5b400d9a24d4f60', 'The negative term is always on the left. The first 4 measure pragmatic quality; the last 4, hedonic quality.'),
  (gen_random_uuid()::text, 'en', '9a4e71736bd04c92', 'The 8 items'),
  (gen_random_uuid()::text, 'en', '6b693fdd2d2678f8', 'The 8 UEQ-S pairs'),
  (gen_random_uuid()::text, 'en', '38be6e60ef6b0b1c', 'Word pairs'),
  (gen_random_uuid()::text, 'en', 'e24b06506e99c6d1', 'Official UEQ-S spreadsheet (XLSX)'),
  (gen_random_uuid()::text, 'en', 'ad046c0476e87fed', 'Official UEQ-S spreadsheet and data/protocolo-ueq-s.json'),
  (gen_random_uuid()::text, 'en', 'a714567f4023225f', 'Exported official spreadsheet'),
  (gen_random_uuid()::text, 'en', '85813aa17fb73bf5', 'Pragmatic is whether the product helps people do what they need: items 1 to 4 (support, ease, efficiency and clarity). Hedonic is whether using it is pleasant and interesting: items 5 to 8 (exciting, interesting, inventive and innovative). The UEQ-S does not separate the 6 scales of the full UEQ.'),
  (gen_random_uuid()::text, 'en', 'ef0e1e29b2f962d8', 'When the full version does not fit: little time, the UEQ inside a longer questionnaire, or the same person rating several products in a row'),
  (gen_random_uuid()::text, 'en', '1cca5e91e7af19e4', 'When to use'),
  (gen_random_uuid()::text, 'en', '7f9e52e1d71739db', 'Questionnaire'),
  (gen_random_uuid()::text, 'en', '58fd4e45864dabe5', 'Study questionnaire'),
  (gen_random_uuid()::text, 'en', '14840a1d0ddcfedc', 'Questionnaire: UEQ or UEQ-S'),
  (gen_random_uuid()::text, 'en', '773e4c885727a324', 'UEQ-S results by scale (CSV)'),
  (gen_random_uuid()::text, 'en', '729142a8a48c4260', 'If the study uses the UEQ-S, the CSV has 8 columns, in the UEQ-S order, as in the Data sheet of the official UEQ-S spreadsheet.'),
  (gen_random_uuid()::text, 'en', '9cdfdcbc7651d71c', 'Only pragmatic quality, hedonic quality and an overall score'),
  (gen_random_uuid()::text, 'en', 'b34e5952b4b2083e', 'Time to answer'),
  (gen_random_uuid()::text, 'en', 'fbdd1e04c28b7a98', 'Full UEQ'),
  (gen_random_uuid()::text, 'en', '610ae398d878994a', 'UEQ or UEQ-S'),
  (gen_random_uuid()::text, 'en', '9e528d7c059e370e', 'UEQ-S · {titulo} · Ferramenta UEQ'),
  (gen_random_uuid()::text, 'en', '1b445fb03d286686', 'UEQ-S, short version'),
  (gen_random_uuid()::text, 'en', '144bff43d73703cd', 'UEQ-S, short version · 8 items · {length} languages'),
  (gen_random_uuid()::text, 'en', '0047e4cd8189b5b1', 'One row per participation, the 8 values from 1 to 7 in the UEQ-S order, with columns for inclusion in the analysis and suspicion.'),
  (gen_random_uuid()::text, 'en', '05daef7262999aa0', 'One person per row, with the 8 values from 1 to 7 in the UEQ-S order and no header, as in the Data sheet of the official UEQ-S spreadsheet. Separated by semicolon, comma or tab. Up to 5000 rows.'),
  (gen_random_uuid()::text, 'en', '72786137971549ab', 'See the difference between the UEQ and the UEQ-S'),
  (gen_random_uuid()::text, 'en', 'c9eb02e0f5cf4c07', 'n, mean, SD, CI95, alpha and bands of pragmatic, hedonic and overall quality, by version, only with the participations in the analysis.'),
  (gen_random_uuid()::text, 'en', 'e6f8b54eeeb50370', 'n, mean, SD, CI95, alpha and bands of pragmatic, hedonic and overall quality, by version. The raw responses are exported from the UEQ tab.'),
  (gen_random_uuid()::text, 'en', 'af36e8d398f2f8b1', 'the questionnaire the participant answers, the time stated in the consent form, the results dashboard and the official spreadsheet you export. The UEQ-S does not have the 6 scales: only pragmatic quality, hedonic quality and an overall score.'),
  (gen_random_uuid()::text, 'en', 'e699fde816de1872', 'all in the middle'),
  (gen_random_uuid()::text, 'en', '9c8ebeb323bd0fb0', 'It is the mean of the 8 items. The handbook asks for care: it is not a single indicator of experience, because the weight of pragmatic and hedonic quality varies from one product to another. Always read it together with both.'),
  (gen_random_uuid()::text, 'es', 'a4079029268e4660', ', todas en la posición del medio.'),
  (gen_random_uuid()::text, 'es', '0b1c60f0d880a91c', '26 pares de palabras · de 3 a 5 minutos'),
  (gen_random_uuid()::text, 'es', 'b4d12aab565dedaa', '8 pares de palabras · de 1 a 2 minutos'),
  (gen_random_uuid()::text, 'es', '3bd0b54b3c644bf9', '8, tomados de los 26'),
  (gen_random_uuid()::text, 'es', '00bf7ea7a7150a2c', 'La UEQ-S Data Analysis Tool V15 ya rellenada con {quantidade} de la versión {nome} que están en el análisis. Ábrela en Excel y haz clic en Habilitar edición: la hoja recalcula sola, con sus gráficos, el benchmark y las respuestas sospechosas.'),
  (gen_random_uuid()::text, 'es', 'f9150f74d9f74fe5', 'La UEQ-S Data Analysis Tool V15 ya rellenada con {quantidade} que están en el análisis. Ábrela en Excel y haz clic en Habilitar edición: la hoja recalcula sola, con sus gráficos, el benchmark y las respuestas sospechosas.'),
  (gen_random_uuid()::text, 'es', '7a7c53d439c4bf48', 'La pestaña UEQ-S muestra la evaluación de la versión corta: calidad pragmática, hedónica y general, con su benchmark y su hoja oficial. En un estudio del UEQ-S es el panel completo; en uno del UEQ completo, usa los 8 pares del UEQ-S que los participantes también respondieron.'),
  (gen_random_uuid()::text, 'es', 'f1ae8e277add0379', 'La misma comparación con la base oficial, en cinco franjas, de Excelente (entre el 10% mejor) a Malo (entre el 25% peor). La hoja oficial del UEQ-S advierte que aún no hay datos suficientes de la versión corta: los límites vienen de los mismos 8 ítems dentro del UEQ completo y son una aproximación, para leer con cuidado.'),
  (gen_random_uuid()::text, 'es', 'ce2f7def94215f23', 'La misma posición se marcó en {iguais} de los 8 ítems{v}'),
  (gen_random_uuid()::text, 'es', 'a7a4e2547797b3dc', 'Aún no hay datos suficientes de la versión corta: los límites del UEQ-S vienen de los mismos 8 ítems dentro del UEQ completo. Usa las franjas como una primera estimación.'),
  (gen_random_uuid()::text, 'es', 'ef299d5bbf1652c9', 'Aproximado: los límites aún vienen de los mismos 8 ítems dentro del UEQ completo'),
  (gen_random_uuid()::text, 'es', 'ba3669e3ba121cc2', 'Las 2 escalas inconsistentes, o la posición del medio ({meio}) en los 8 ítems'),
  (gen_random_uuid()::text, 'es', '04a4bec03d5421ad', 'Las 6 escalas y, a partir de ellas, la calidad pragmática y la hedónica'),
  (gen_random_uuid()::text, 'es', 'ff1816b44eeac188', 'Las medias, los intervalos de confianza, el alfa y el benchmark de la calidad pragmática, la hedónica y la general aparecen aquí en cuanto llegue la primera respuesta.'),
  (gen_random_uuid()::text, 'es', '8362db625cf11792', 'Benchmark aproximado.'),
  (gen_random_uuid()::text, 'es', '4ec93dc43d6943cf', 'Cada punto es la media de las respuestas al par, del término de la izquierda (-3) al de la derecha (+3). En el UEQ-S el término negativo está siempre a la izquierda.'),
  (gen_random_uuid()::text, 'es', 'd4679986e4a13fa2', '¿Cómo leer la escala general?'),
  (gen_random_uuid()::text, 'es', '15900c5ffe6b043b', 'De 1 a 2 minutos'),
  (gen_random_uuid()::text, 'es', 'd84a57665a63d405', 'De 1 a 2 minutos · voluntaria y anónima'),
  (gen_random_uuid()::text, 'es', '56deeeb5cd215073', 'De 2 a 3 minutos · voluntaria y anónima'),
  (gen_random_uuid()::text, 'es', '6299af052f4defd9', 'De 3 a 5 minutos'),
  (gen_random_uuid()::text, 'es', 'f426d43aed1aae02', 'Después de la primera respuesta la elección se bloquea, para que el estudio no mezcle los dos cuestionarios.'),
  (gen_random_uuid()::text, 'es', '2a804d05f2c8bc31', 'Diferencias entre el UEQ completo y el UEQ-S'),
  (gen_random_uuid()::text, 'es', '1c3de5d03a2c189d', 'Escalas del UEQ-S'),
  (gen_random_uuid()::text, 'es', 'b2fdc6cdf7a4e017', 'Elige el cuestionario: UEQ completo o UEQ-S.'),
  (gen_random_uuid()::text, 'es', 'b50ee17343aec113', 'Estudio del UEQ-S'),
  (gen_random_uuid()::text, 'es', '51658f25775c996d', 'Ferramenta UEQ · Panel de resultados del UEQ-S'),
  (gen_random_uuid()::text, 'es', 'f1d3445f45dc3300', 'General'),
  (gen_random_uuid()::text, 'es', '3b297def8e05630a', 'Ítem {numero}: de {esquerdo} a {direito}'),
  (gen_random_uuid()::text, 'es', '98f022d65a10c65c', 'Ítems 1 a 4'),
  (gen_random_uuid()::text, 'es', 'adcce322242c323d', 'Ítems 5 a 8'),
  (gen_random_uuid()::text, 'es', 'dd339111f097feb6', 'Mide las 6 escalas (Atractivo, Perspicuidad, Eficiencia, Confiabilidad, Estimulación y Novedad) y, a partir de ellas, la calidad pragmática y la hedónica. Es el recomendado para la mayoría de los estudios, como después de una prueba de usabilidad.'),
  (gen_random_uuid()::text, 'es', 'a61910ac3ff95713', 'Mide solo la calidad pragmática, la calidad hedónica y una nota general, sin las 6 escalas. Sirve cuando el completo no cabe: poco tiempo, el UEQ dentro de un cuestionario más largo o la misma persona evaluando varios productos seguidos.'),
  (gen_random_uuid()::text, 'es', '8597715d8249479a', 'Mismo formato, con valores de -3 a +3. En el UEQ-S el término positivo está siempre a la derecha.'),
  (gen_random_uuid()::text, 'es', 'dd96696d8f635d25', 'Medias de las tres escalas del UEQ-S con intervalo de confianza del 95% y franjas del benchmark.'),
  (gen_random_uuid()::text, 'es', '1e255e23d55c6fae', 'En la mayoría de los estudios, como después de una prueba de usabilidad'),
  (gen_random_uuid()::text, 'es', 'c0d82be82fc68e75', 'En un estudio del UEQ completo, los resultados también muestran el UEQ-S, en una pestaña propia, calculado con sus 8 pares.'),
  (gen_random_uuid()::text, 'es', '2b516db65a9ff8e6', 'El UEQ completo tiene 26 pares y mide las 6 escalas; es el recomendado en la mayoría de los estudios. El UEQ-S tiene 8 de esos pares, lleva de 1 a 2 minutos y mide solo la calidad pragmática, la hedónica y una nota general; úsalo cuando el completo no cabe. La elección cambia el cuestionario, el panel y la hoja exportada, y se bloquea con la primera respuesta.'),
  (gen_random_uuid()::text, 'es', 'aea48ff81a944c25', 'El UEQ tiene dos formas. Las dos usan los mismos pares de palabras opuestas y la misma escala de 7 posiciones; la versión corta usa solo 8 de los 26 pares.'),
  (gen_random_uuid()::text, 'es', '6d0c31c3f5025db1', 'El UEQ-S a partir del UEQ completo.'),
  (gen_random_uuid()::text, 'es', 'd37e05a5e11d0ce3', 'El UEQ-S son 8 de los 26 pares: 11, 13, 20 y 21 (calidad pragmática) y 6, 7, 10 y 15 (calidad hedónica). Esta pestaña usa las respuestas que los participantes dieron a esos pares, del mismo modo en que los autores construyeron el UEQ-S y su benchmark. Para las 6 escalas, vuelve a la pestaña Escalas del UEQ.'),
  (gen_random_uuid()::text, 'es', '6019d611a7d470f0', 'El UEQ-S es la versión corta del UEQ: 8 de los mismos 26 pares, con la misma escala de 7 posiciones. Se responde más rápido, pero no separa las 6 escalas. Eliges uno de los dos al crear el estudio.'),
  (gen_random_uuid()::text, 'es', 'bae875592e85a23c', 'El estudio ya tiene respuestas, así que el cuestionario ya no puede cambiar. Para usar el otro, crea un estudio nuevo.'),
  (gen_random_uuid()::text, 'es', '3b30696110490a7b', 'El oficial, con 21.175 personas de 468 estudios'),
  (gen_random_uuid()::text, 'es', 'e124308087e6e9c0', 'Qué mide'),
  (gen_random_uuid()::text, 'es', '42f77b4043940783', 'Qué cambia con la elección:'),
  (gen_random_uuid()::text, 'es', '3c3472b75b92e9b3', '¿Qué son la calidad pragmática y la hedónica?'),
  (gen_random_uuid()::text, 'es', '068ea3511e50f59a', '¿Qué es el benchmark del UEQ-S?'),
  (gen_random_uuid()::text, 'es', 'e5b400d9a24d4f60', 'El término negativo está siempre a la izquierda. Los 4 primeros miden la calidad pragmática; los 4 últimos, la hedónica.'),
  (gen_random_uuid()::text, 'es', '9a4e71736bd04c92', 'Los 8 ítems'),
  (gen_random_uuid()::text, 'es', '6b693fdd2d2678f8', 'Los 8 pares del UEQ-S'),
  (gen_random_uuid()::text, 'es', '38be6e60ef6b0b1c', 'Pares de palabras'),
  (gen_random_uuid()::text, 'es', 'e24b06506e99c6d1', 'Hoja oficial del UEQ-S (XLSX)'),
  (gen_random_uuid()::text, 'es', 'ad046c0476e87fed', 'Hoja oficial del UEQ-S y data/protocolo-ueq-s.json'),
  (gen_random_uuid()::text, 'es', 'a714567f4023225f', 'Hoja oficial exportada'),
  (gen_random_uuid()::text, 'es', '85813aa17fb73bf5', 'Pragmática es si el producto ayuda a hacer lo que la persona necesita: los ítems 1 a 4 (apoyo, facilidad, eficiencia y claridad). Hedónica es si usarlo es agradable e interesante: los ítems 5 a 8 (emocionante, interesante, original e innovador). El UEQ-S no separa las 6 escalas del UEQ completo.'),
  (gen_random_uuid()::text, 'es', 'ef0e1e29b2f962d8', 'Cuando el completo no cabe: poco tiempo, el UEQ dentro de un cuestionario más largo, o la misma persona evaluando varios productos seguidos'),
  (gen_random_uuid()::text, 'es', '1cca5e91e7af19e4', 'Cuándo usarlo'),
  (gen_random_uuid()::text, 'es', '7f9e52e1d71739db', 'Cuestionario'),
  (gen_random_uuid()::text, 'es', '58fd4e45864dabe5', 'Cuestionario del estudio'),
  (gen_random_uuid()::text, 'es', '14840a1d0ddcfedc', 'Cuestionario: UEQ o UEQ-S'),
  (gen_random_uuid()::text, 'es', '773e4c885727a324', 'Resultados del UEQ-S por escala (CSV)'),
  (gen_random_uuid()::text, 'es', '729142a8a48c4260', 'Si el estudio usa el UEQ-S, el CSV tiene 8 columnas, en el orden del UEQ-S, como en la pestaña Data de la hoja oficial del UEQ-S.'),
  (gen_random_uuid()::text, 'es', '9cdfdcbc7651d71c', 'Solo calidad pragmática, calidad hedónica y una nota general'),
  (gen_random_uuid()::text, 'es', 'b34e5952b4b2083e', 'Tiempo para responder'),
  (gen_random_uuid()::text, 'es', 'fbdd1e04c28b7a98', 'UEQ completo'),
  (gen_random_uuid()::text, 'es', '610ae398d878994a', 'UEQ o UEQ-S'),
  (gen_random_uuid()::text, 'es', '9e528d7c059e370e', 'UEQ-S · {titulo} · Ferramenta UEQ'),
  (gen_random_uuid()::text, 'es', '1b445fb03d286686', 'UEQ-S, versión corta'),
  (gen_random_uuid()::text, 'es', '144bff43d73703cd', 'UEQ-S, versión corta · 8 ítems · {length} idiomas'),
  (gen_random_uuid()::text, 'es', '0047e4cd8189b5b1', 'Una fila por participación, los 8 valores de 1 a 7 en el orden del UEQ-S, con columnas de inclusión en el análisis y de sospecha.'),
  (gen_random_uuid()::text, 'es', '05daef7262999aa0', 'Una persona por fila, con los 8 valores de 1 a 7 en el orden del UEQ-S y sin encabezado, como en la pestaña Data de la hoja oficial del UEQ-S. Separados por punto y coma, coma o tabulación. Hasta 5000 filas.'),
  (gen_random_uuid()::text, 'es', '72786137971549ab', 'Ver la diferencia entre el UEQ y el UEQ-S'),
  (gen_random_uuid()::text, 'es', 'c9eb02e0f5cf4c07', 'n, media, DE, IC95, alfa y franjas de la calidad pragmática, la hedónica y la general, por versión, solo con las participaciones en el análisis.'),
  (gen_random_uuid()::text, 'es', 'e6f8b54eeeb50370', 'n, media, DE, IC95, alfa y franjas de la calidad pragmática, la hedónica y la general, por versión. Las respuestas brutas se exportan en la pestaña del UEQ.'),
  (gen_random_uuid()::text, 'es', 'af36e8d398f2f8b1', 'el cuestionario que responde el participante, el tiempo indicado en el consentimiento, el panel de resultados y la hoja oficial que exportas. El UEQ-S no tiene las 6 escalas: solo calidad pragmática, calidad hedónica y una nota general.'),
  (gen_random_uuid()::text, 'es', 'e699fde816de1872', 'todas en el medio'),
  (gen_random_uuid()::text, 'es', '9c8ebeb323bd0fb0', 'Es la media de los 8 ítems. El manual pide cuidado: no es un indicador único de la experiencia, porque el peso de la calidad pragmática y de la hedónica cambia de un producto a otro. Léela siempre junto con las dos.'),
  (gen_random_uuid()::text, 'de', 'a4079029268e4660', ', alle in der mittleren Position.'),
