  (gen_random_uuid()::text, 'de', '9e528d7c059e370e', 'UEQ-S · {titulo} · Ferramenta UEQ'),
  (gen_random_uuid()::text, 'de', '1b445fb03d286686', 'UEQ-S, Kurzversion'),
