  (gen_random_uuid()::text, 'fr', '068ea3511e50f59a', 'Qu''est-ce que le benchmark de l''UEQ-S ?'),
  (gen_random_uuid()::text, 'fr', 'e5b400d9a24d4f60', 'Le terme négatif est toujours à gauche. Les 4 premiers mesurent la qualité pragmatique ; les 4 derniers, la qualité hédonique.'),
  (gen_random_uuid()::text, 'fr', '9a4e71736bd04c92', 'Les 8 items'),
  (gen_random_uuid()::text, 'fr', '6b693fdd2d2678f8', 'Les 8 paires de l''UEQ-S'),
  (gen_random_uuid()::text, 'fr', '38be6e60ef6b0b1c', 'Paires de mots'),
  (gen_random_uuid()::text, 'fr', 'e24b06506e99c6d1', 'Feuille officielle de l''UEQ-S (XLSX)'),
