  (gen_random_uuid()::text, 'it', '3bd0b54b3c644bf9', '8, prese dalle 26'),
  (gen_random_uuid()::text, 'it', '00bf7ea7a7150a2c', 'La UEQ-S Data Analysis Tool V15 già compilata con {quantidade} della versione {nome} incluse nell''analisi. Aprila in Excel e fai clic su Abilita modifica: il foglio si ricalcola da solo, con i suoi grafici, il benchmark e le risposte sospette.'),
  (gen_random_uuid()::text, 'it', 'f9150f74d9f74fe5', 'La UEQ-S Data Analysis Tool V15 già compilata con {quantidade} incluse nell''analisi. Aprila in Excel e fai clic su Abilita modifica: il foglio si ricalcola da solo, con i suoi grafici, il benchmark e le risposte sospette.'),
  (gen_random_uuid()::text, 'it', '7a7c53d439c4bf48', 'La scheda UEQ-S mostra la valutazione della versione breve: qualità pragmatica, edonica e complessiva, con il suo benchmark e il suo foglio ufficiale. In uno studio UEQ-S è l''intero pannello; in uno studio con l''UEQ completo usa le 8 coppie dell''UEQ-S a cui i partecipanti hanno risposto.'),
  (gen_random_uuid()::text, 'it', 'f1ae8e277add0379', 'Lo stesso confronto con la base ufficiale, in cinque fasce, da Eccellente (tra il 10% migliore) a Scarso (tra il 25% peggiore). Il foglio ufficiale dell''UEQ-S avverte che non ci sono ancora dati sufficienti sulla versione breve: i limiti provengono dagli stessi 8 item all''interno dell''UEQ completo e sono un''approssimazione, da leggere con cautela.'),
  (gen_random_uuid()::text, 'it', 'ce2f7def94215f23', 'La stessa posizione è stata segnata in {iguais} degli 8 item{v}'),
  (gen_random_uuid()::text, 'it', 'a7a4e2547797b3dc', 'Non ci sono ancora dati sufficienti sulla versione breve: i limiti dell''UEQ-S provengono dagli stessi 8 item all''interno dell''UEQ completo. Usa le fasce come una prima stima.'),
  (gen_random_uuid()::text, 'it', 'ef299d5bbf1652c9', 'Approssimato: i limiti provengono ancora dagli stessi 8 item all''interno dell''UEQ completo'),
