  (gen_random_uuid()::text, 'cs', 'aea48ff81a944c25', 'UEQ má dvě podoby. Obě používají stejné dvojice protikladných slov a stejnou 7bodovou škálu; krátká verze používá jen 8 z 26 dvojic.'),
