  (gen_random_uuid()::text, 'fa', '2b516db65a9ff8e6', 'UEQ کامل ۲۶ جفت دارد و ۶ مقیاس را می‌سنجد؛ برای بیشتر مطالعات توصیه می‌شود. UEQ-S هشت جفت از همین‌ها را دارد، ۱ تا ۲ دقیقه طول می‌کشد و فقط کیفیت عملگرا، کیفیت هدونیک و یک نمرهٔ کلی را می‌سنجد؛ وقتی نسخهٔ کامل جا نمی‌شود از آن استفاده کنید. انتخاب، پرسش‌نامه، داشبورد و صفحه‌گستردهٔ خروجی را تغییر می‌دهد و با نخستین پاسخ قفل می‌شود.'),
  (gen_random_uuid()::text, 'fa', 'aea48ff81a944c25', 'UEQ دو شکل دارد. هر دو از همان جفت‌واژه‌های متضاد و همان مقیاس ۷ موقعیتی استفاده می‌کنند؛ نسخهٔ کوتاه فقط ۸ جفت از ۲۶ جفت را به کار می‌برد.'),
  (gen_random_uuid()::text, 'fa', '6d0c31c3f5025db1', 'UEQ-S بر پایهٔ UEQ کامل.'),
  (gen_random_uuid()::text, 'fa', 'd37e05a5e11d0ce3', 'UEQ-S هشت جفت از ۲۶ جفت است: ۱۱، ۱۳، ۲۰ و ۲۱ (کیفیت عملگرا) و ۶، ۷، ۱۰ و ۱۵ (کیفیت هدونیک). این زبانه از پاسخ‌های شرکت‌کنندگان به این جفت‌ها استفاده می‌کند، همان‌طور که نویسندگان UEQ-S و بنچمارک آن را ساختند. برای ۶ مقیاس، به زبانهٔ مقیاس‌های UEQ برگردید.'),
  (gen_random_uuid()::text, 'fa', '6019d611a7d470f0', 'UEQ-S نسخهٔ کوتاه UEQ است: ۸ جفت از همان ۲۶ جفت، با همان مقیاس ۷ موقعیتی. پاسخ دادن به آن سریع‌تر است، اما ۶ مقیاس را از هم جدا نمی‌کند. هنگام ساختن مطالعه یکی از این دو را انتخاب می‌کنید.'),
  (gen_random_uuid()::text, 'fa', 'bae875592e85a23c', 'مطالعه از قبل پاسخ دارد، پس پرسش‌نامه دیگر قابل تغییر نیست. برای استفاده از دیگری، مطالعهٔ تازه‌ای بسازید.'),
  (gen_random_uuid()::text, 'fa', '3b30696110490a7b', 'رسمی، با ۲۱٬۱۷۵ نفر از ۴۶۸ مطالعه'),
  (gen_random_uuid()::text, 'fa', 'e124308087e6e9c0', 'چه چیزی را می‌سنجد'),
  (gen_random_uuid()::text, 'fa', '42f77b4043940783', 'آنچه انتخاب تغییر می‌دهد:'),
  (gen_random_uuid()::text, 'fa', '3c3472b75b92e9b3', 'کیفیت عملگرا و هدونیک چیست؟'),
  (gen_random_uuid()::text, 'fa', '068ea3511e50f59a', 'بنچمارک UEQ-S چیست؟'),
  (gen_random_uuid()::text, 'fa', 'e5b400d9a24d4f60', 'واژهٔ منفی همیشه سمت چپ است. ۴ گویهٔ نخست کیفیت عملگرا و ۴ گویهٔ آخر کیفیت هدونیک را می‌سنجند.'),
  (gen_random_uuid()::text, 'fa', '9a4e71736bd04c92', '۸ گویه'),
  (gen_random_uuid()::text, 'fa', '6b693fdd2d2678f8', '۸ جفت UEQ-S'),
  (gen_random_uuid()::text, 'fa', '38be6e60ef6b0b1c', 'جفت‌واژه‌ها'),
  (gen_random_uuid()::text, 'fa', 'e24b06506e99c6d1', 'صفحه‌گستردهٔ رسمی UEQ-S (XLSX)'),
  (gen_random_uuid()::text, 'fa', 'ad046c0476e87fed', 'صفحه‌گستردهٔ رسمی UEQ-S و data/protocolo-ueq-s.json'),
  (gen_random_uuid()::text, 'fa', 'a714567f4023225f', 'صفحه‌گستردهٔ رسمی خروجی'),
  (gen_random_uuid()::text, 'fa', '85813aa17fb73bf5', 'عملگرا یعنی آیا محصول به فرد کمک می‌کند کاری را که لازم دارد انجام دهد: گویه‌های ۱ تا ۴ (پشتیبانی، سادگی، کارایی و وضوح). هدونیک یعنی آیا استفاده از آن خوشایند و جالب است: گویه‌های ۵ تا ۸ (هیجان‌انگیز، جالب، خلاقانه و نوآورانه). UEQ-S شش مقیاس UEQ کامل را از هم جدا نمی‌کند.'),
  (gen_random_uuid()::text, 'fa', 'ef0e1e29b2f962d8', 'وقتی نسخهٔ کامل جا نمی‌شود: وقت کم، UEQ درون پرسش‌نامه‌ای طولانی‌تر، یا یک نفر که چند محصول را پشت سر هم ارزیابی می‌کند'),
  (gen_random_uuid()::text, 'fa', '1cca5e91e7af19e4', 'چه وقت استفاده کنیم'),
