  (gen_random_uuid()::text, 'fa', '9cdfdcbc7651d71c', 'فقط کیفیت عملگرا، کیفیت هدونیک و یک نمرهٔ کلی'),
  (gen_random_uuid()::text, 'fa', 'b34e5952b4b2083e', 'زمان پاسخ‌گویی'),
  (gen_random_uuid()::text, 'fa', 'fbdd1e04c28b7a98', 'UEQ کامل'),
  (gen_random_uuid()::text, 'fa', '610ae398d878994a', 'UEQ یا UEQ-S'),
  (gen_random_uuid()::text, 'fa', '9e528d7c059e370e', 'UEQ-S · {titulo} · Ferramenta UEQ'),
  (gen_random_uuid()::text, 'fa', '1b445fb03d286686', 'UEQ-S، نسخهٔ کوتاه'),
  (gen_random_uuid()::text, 'fa', '144bff43d73703cd', 'UEQ-S، نسخهٔ کوتاه · ۸ گویه · {length} زبان'),
  (gen_random_uuid()::text, 'fa', '0047e4cd8189b5b1', 'یک ردیف برای هر مشارکت، ۸ مقدار ۱ تا ۷ به ترتیب UEQ-S، با ستون‌های حضور در تحلیل و مشکوک بودن.'),
  (gen_random_uuid()::text, 'fa', '05daef7262999aa0', 'هر ردیف یک نفر، با ۸ مقدار ۱ تا ۷ به ترتیب UEQ-S و بدون سرستون، مانند برگهٔ Data در صفحه‌گستردهٔ رسمی UEQ-S. جداشده با نقطه‌ویرگول، ویرگول یا تب. حداکثر ۵۰۰۰ ردیف.'),
  (gen_random_uuid()::text, 'fa', '72786137971549ab', 'تفاوت UEQ و UEQ-S را ببینید'),
  (gen_random_uuid()::text, 'fa', 'c9eb02e0f5cf4c07', 'n، میانگین، انحراف معیار، بازهٔ اطمینان ۹۵٪، آلفا و بازه‌های کیفیت عملگرا، هدونیک و کلی، بر حسب نسخه، فقط با مشارکت‌های درون تحلیل.'),
  (gen_random_uuid()::text, 'fa', 'e6f8b54eeeb50370', 'n، میانگین، انحراف معیار، بازهٔ اطمینان ۹۵٪، آلفا و بازه‌های کیفیت عملگرا، هدونیک و کلی، بر حسب نسخه. پاسخ‌های خام از زبانهٔ UEQ خروجی گرفته می‌شوند.'),
  (gen_random_uuid()::text, 'fa', 'af36e8d398f2f8b1', 'پرسش‌نامه‌ای که شرکت‌کننده پاسخ می‌دهد، زمانی که در فرم رضایت آمده، داشبورد نتایج و صفحه‌گستردهٔ رسمی که خروجی می‌گیرید. UEQ-S شش مقیاس را ندارد: فقط کیفیت عملگرا، کیفیت هدونیک و یک نمرهٔ کلی.'),
  (gen_random_uuid()::text, 'fa', 'e699fde816de1872', 'همه در میانه'),
  (gen_random_uuid()::text, 'fa', '9c8ebeb323bd0fb0', 'این میانگین ۸ گویه است. راهنما به احتیاط سفارش می‌کند: این یک شاخص واحد تجربه نیست، چون وزن کیفیت عملگرا و هدونیک از محصولی به محصول دیگر فرق می‌کند. همیشه آن را همراه با آن دو بخوانید.'),
  (gen_random_uuid()::text, 'hi', 'a4079029268e4660', ', सभी बीच वाली स्थिति में।'),
  (gen_random_uuid()::text, 'hi', '0b1c60f0d880a91c', '26 शब्द-युग्म · 3 से 5 मिनट'),
  (gen_random_uuid()::text, 'hi', 'b4d12aab565dedaa', '8 शब्द-युग्म · 1 से 2 मिनट'),
  (gen_random_uuid()::text, 'hi', '3bd0b54b3c644bf9', '8, 26 में से लिए गए'),
  (gen_random_uuid()::text, 'hi', '00bf7ea7a7150a2c', 'UEQ-S Data Analysis Tool V15, जिसमें संस्करण {nome} की विश्लेषण में शामिल {quantidade} पहले से भरी हैं। इसे Excel में खोलें और Enable Editing पर क्लिक करें: स्प्रेडशीट अपने चार्ट, बेंचमार्क और संदिग्ध उत्तरों के साथ खुद फिर से गणना करती है।'),
  (gen_random_uuid()::text, 'hi', 'f9150f74d9f74fe5', 'UEQ-S Data Analysis Tool V15, जिसमें विश्लेषण में शामिल {quantidade} पहले से भरी हैं। इसे Excel में खोलें और Enable Editing पर क्लिक करें: स्प्रेडशीट अपने चार्ट, बेंचमार्क और संदिग्ध उत्तरों के साथ खुद फिर से गणना करती है।'),
  (gen_random_uuid()::text, 'hi', '7a7c53d439c4bf48', 'UEQ-S टैब छोटे संस्करण का मूल्यांकन दिखाता है: व्यावहारिक, सुखद और समग्र गुणवत्ता, उसके बेंचमार्क और आधिकारिक स्प्रेडशीट के साथ। UEQ-S अध्ययन में यही पूरा डैशबोर्ड है; पूर्ण UEQ वाले अध्ययन में यह UEQ-S के उन 8 युग्मों का उपयोग करता है जिनके उत्तर प्रतिभागियों ने भी दिए।'),
  (gen_random_uuid()::text, 'hi', 'f1ae8e277add0379', 'आधिकारिक डेटा सेट से वही तुलना, पाँच श्रेणियों में, उत्कृष्ट (सबसे अच्छे 10% में) से खराब (सबसे कमज़ोर 25% में) तक। UEQ-S की आधिकारिक स्प्रेडशीट चेतावनी देती है कि छोटे संस्करण का अभी पर्याप्त डेटा नहीं है: सीमाएँ पूर्ण UEQ के भीतर उन्हीं 8 मदों से आती हैं और अनुमानित हैं, इसलिए उन्हें सावधानी से पढ़ें।'),
  (gen_random_uuid()::text, 'hi', 'ce2f7def94215f23', '8 में से {iguais} मदों में एक ही स्थिति चुनी गई{v}'),
  (gen_random_uuid()::text, 'hi', 'a7a4e2547797b3dc', 'छोटे संस्करण का अभी पर्याप्त डेटा नहीं है: UEQ-S की सीमाएँ पूर्ण UEQ के भीतर उन्हीं 8 मदों से आती हैं। श्रेणियों को पहले अनुमान के रूप में लें।'),
  (gen_random_uuid()::text, 'hi', 'ef299d5bbf1652c9', 'अनुमानित: सीमाएँ अब भी पूर्ण UEQ के भीतर उन्हीं 8 मदों से आती हैं'),
  (gen_random_uuid()::text, 'hi', 'ba3669e3ba121cc2', 'दोनों पैमाने असंगत, या सभी 8 मदों में बीच वाली स्थिति ({meio})'),
  (gen_random_uuid()::text, 'hi', '04a4bec03d5421ad', '6 पैमाने और, उनके आधार पर, व्यावहारिक और सुखद गुणवत्ता'),
  (gen_random_uuid()::text, 'hi', 'ff1816b44eeac188', 'व्यावहारिक, सुखद और समग्र गुणवत्ता के औसत, विश्वास अंतराल, अल्फ़ा और बेंचमार्क पहला उत्तर आते ही यहाँ दिखेंगे।'),
  (gen_random_uuid()::text, 'hi', '8362db625cf11792', 'अनुमानित बेंचमार्क।'),
  (gen_random_uuid()::text, 'hi', '4ec93dc43d6943cf', 'हर बिंदु युग्म के उत्तरों का औसत है, बाएँ शब्द (-3) से दाएँ शब्द (+3) तक। UEQ-S में नकारात्मक शब्द हमेशा बाईं ओर होता है।'),
  (gen_random_uuid()::text, 'hi', 'd4679986e4a13fa2', 'समग्र पैमाना कैसे पढ़ें?'),
  (gen_random_uuid()::text, 'hi', '15900c5ffe6b043b', '1 से 2 मिनट'),
  (gen_random_uuid()::text, 'hi', 'd84a57665a63d405', '1 से 2 मिनट · स्वैच्छिक और अनाम'),
  (gen_random_uuid()::text, 'hi', '56deeeb5cd215073', '2 से 3 मिनट · स्वैच्छिक और अनाम'),
  (gen_random_uuid()::text, 'hi', '6299af052f4defd9', '3 से 5 मिनट'),
  (gen_random_uuid()::text, 'hi', 'f426d43aed1aae02', 'पहले उत्तर के बाद चुनाव लॉक हो जाता है, ताकि अध्ययन दोनों प्रश्नावलियों को मिला न दे।'),
  (gen_random_uuid()::text, 'hi', '2a804d05f2c8bc31', 'पूर्ण UEQ और UEQ-S के बीच अंतर'),
  (gen_random_uuid()::text, 'hi', '1c3de5d03a2c189d', 'UEQ-S के पैमाने'),
  (gen_random_uuid()::text, 'hi', 'b2fdc6cdf7a4e017', 'प्रश्नावली चुनें: पूर्ण UEQ या UEQ-S।'),
  (gen_random_uuid()::text, 'hi', 'b50ee17343aec113', 'UEQ-S अध्ययन'),
  (gen_random_uuid()::text, 'hi', '51658f25775c996d', 'Ferramenta UEQ · UEQ-S परिणाम डैशबोर्ड'),
  (gen_random_uuid()::text, 'hi', 'f1d3445f45dc3300', 'समग्र'),
  (gen_random_uuid()::text, 'hi', '3b297def8e05630a', 'मद {numero}: {esquerdo} से {direito} तक'),
  (gen_random_uuid()::text, 'hi', '98f022d65a10c65c', 'मद 1 से 4'),
  (gen_random_uuid()::text, 'hi', 'adcce322242c323d', 'मद 5 से 8'),
  (gen_random_uuid()::text, 'hi', 'dd339111f097feb6', '6 पैमाने (आकर्षण, स्पष्टता, दक्षता, विश्वसनीयता, उत्तेजना और नवीनता) और, उनके आधार पर, व्यावहारिक और सुखद गुणवत्ता मापता है। ज़्यादातर अध्ययनों के लिए यही सुझाया जाता है, जैसे उपयोगिता परीक्षण के बाद।'),
  (gen_random_uuid()::text, 'hi', 'a61910ac3ff95713', 'केवल व्यावहारिक गुणवत्ता, सुखद गुणवत्ता और एक समग्र अंक मापता है, 6 पैमानों के बिना। तब के लिए जब पूर्ण प्रश्नावली फिट न हो: कम समय, किसी लंबी प्रश्नावली के भीतर UEQ, या एक ही व्यक्ति लगातार कई उत्पादों का मूल्यांकन करे।'),
  (gen_random_uuid()::text, 'hi', '8597715d8249479a', 'वही प्रारूप, -3 से +3 तक के मानों के साथ। UEQ-S में सकारात्मक शब्द हमेशा दाईं ओर होता है।'),
  (gen_random_uuid()::text, 'hi', 'dd96696d8f635d25', 'UEQ-S के तीन पैमानों के औसत, 95% विश्वास अंतराल और बेंचमार्क श्रेणियों के साथ।'),
  (gen_random_uuid()::text, 'hi', '1e255e23d55c6fae', 'ज़्यादातर अध्ययनों में, जैसे उपयोगिता परीक्षण के बाद'),
  (gen_random_uuid()::text, 'hi', 'c0d82be82fc68e75', 'पूर्ण UEQ वाले अध्ययन में, परिणाम अलग टैब में UEQ-S भी दिखाते हैं, जो उसके 8 युग्मों से गणना किया जाता है।'),
  (gen_random_uuid()::text, 'hi', '2b516db65a9ff8e6', 'पूर्ण UEQ में 26 युग्म हैं और यह 6 पैमाने मापता है; ज़्यादातर अध्ययनों के लिए यही सुझाया जाता है। UEQ-S में इनमें से 8 युग्म हैं, इसमें 1 से 2 मिनट लगते हैं और यह केवल व्यावहारिक गुणवत्ता, सुखद गुणवत्ता और एक समग्र अंक मापता है; जब पूर्ण फिट न हो तब इसका उपयोग करें। चुनाव से प्रश्नावली, डैशबोर्ड और निर्यात की गई स्प्रेडशीट बदलती है, और पहले उत्तर पर यह लॉक हो जाता है।'),
  (gen_random_uuid()::text, 'hi', 'aea48ff81a944c25', 'UEQ के दो रूप हैं। दोनों विपरीत शब्दों के वही युग्म और वही 7 स्थितियों वाला पैमाना उपयोग करते हैं; छोटा संस्करण 26 में से केवल 8 युग्म उपयोग करता है।'),
  (gen_random_uuid()::text, 'hi', '6d0c31c3f5025db1', 'पूर्ण UEQ से UEQ-S।'),
  (gen_random_uuid()::text, 'hi', 'd37e05a5e11d0ce3', 'UEQ-S, 26 में से 8 युग्म हैं: 11, 13, 20 और 21 (व्यावहारिक गुणवत्ता) तथा 6, 7, 10 और 15 (सुखद गुणवत्ता)। यह टैब इन युग्मों पर प्रतिभागियों के उत्तरों का उसी तरह उपयोग करता है जैसे लेखकों ने UEQ-S और उसका बेंचमार्क बनाया। 6 पैमानों के लिए UEQ के पैमाने टैब पर लौटें।'),
  (gen_random_uuid()::text, 'hi', '6019d611a7d470f0', 'UEQ-S, UEQ का छोटा संस्करण है: उन्हीं 26 में से 8 युग्म, उसी 7 स्थितियों वाले पैमाने के साथ। इसका उत्तर जल्दी दिया जाता है, लेकिन यह 6 पैमानों को अलग नहीं करता। अध्ययन बनाते समय आप दोनों में से एक चुनते हैं।'),
  (gen_random_uuid()::text, 'hi', 'bae875592e85a23c', 'अध्ययन में पहले से उत्तर हैं, इसलिए प्रश्नावली अब बदली नहीं जा सकती। दूसरी का उपयोग करने के लिए नया अध्ययन बनाएँ।'),
  (gen_random_uuid()::text, 'hi', '3b30696110490a7b', 'आधिकारिक, 468 अध्ययनों के 21,175 लोगों के साथ'),
  (gen_random_uuid()::text, 'hi', 'e124308087e6e9c0', 'यह क्या मापता है'),
  (gen_random_uuid()::text, 'hi', '42f77b4043940783', 'चुनाव से क्या बदलता है:'),
  (gen_random_uuid()::text, 'hi', '3c3472b75b92e9b3', 'व्यावहारिक और सुखद गुणवत्ता क्या हैं?'),
  (gen_random_uuid()::text, 'hi', '068ea3511e50f59a', 'UEQ-S का बेंचमार्क क्या है?'),
  (gen_random_uuid()::text, 'hi', 'e5b400d9a24d4f60', 'नकारात्मक शब्द हमेशा बाईं ओर होता है। पहले 4 व्यावहारिक गुणवत्ता मापते हैं; आख़िरी 4, सुखद गुणवत्ता।'),
  (gen_random_uuid()::text, 'hi', '9a4e71736bd04c92', '8 मद'),
  (gen_random_uuid()::text, 'hi', '6b693fdd2d2678f8', 'UEQ-S के 8 युग्म'),
  (gen_random_uuid()::text, 'hi', '38be6e60ef6b0b1c', 'शब्द-युग्म'),
  (gen_random_uuid()::text, 'hi', 'e24b06506e99c6d1', 'UEQ-S की आधिकारिक स्प्रेडशीट (XLSX)'),
  (gen_random_uuid()::text, 'hi', 'ad046c0476e87fed', 'UEQ-S की आधिकारिक स्प्रेडशीट और data/protocolo-ueq-s.json'),
  (gen_random_uuid()::text, 'hi', 'a714567f4023225f', 'निर्यात की गई आधिकारिक स्प्रेडशीट'),
  (gen_random_uuid()::text, 'hi', '85813aa17fb73bf5', 'व्यावहारिक का अर्थ है कि उत्पाद व्यक्ति को वह करने में मदद करता है या नहीं जिसकी उसे ज़रूरत है: मद 1 से 4 (सहायता, सरलता, दक्षता और स्पष्टता)। सुखद का अर्थ है कि उपयोग करना सुखद और रोचक है या नहीं: मद 5 से 8 (रोमांचक, रोचक, मौलिक और नवीन)। UEQ-S पूर्ण UEQ के 6 पैमानों को अलग नहीं करता।'),
  (gen_random_uuid()::text, 'hi', 'ef0e1e29b2f962d8', 'जब पूर्ण फिट न हो: कम समय, किसी लंबी प्रश्नावली के भीतर UEQ, या एक ही व्यक्ति लगातार कई उत्पादों का मूल्यांकन करे'),
