  (gen_random_uuid()::text, 'mr', '3bd0b54b3c644bf9', '8, 26 पैकी घेतलेल्या'),
  (gen_random_uuid()::text, 'mr', '00bf7ea7a7150a2c', 'UEQ-S Data Analysis Tool V15, ज्यात आवृत्ती {nome} च्या विश्लेषणात असलेल्या {quantidade} आधीच भरलेल्या आहेत. ते Excel मध्ये उघडा आणि Enable Editing वर क्लिक करा: स्प्रेडशीट तिचे आलेख, बेंचमार्क आणि संशयास्पद उत्तरे यांसह स्वतःच पुन्हा गणना करते.'),
  (gen_random_uuid()::text, 'mr', 'f9150f74d9f74fe5', 'UEQ-S Data Analysis Tool V15, ज्यात विश्लेषणात असलेल्या {quantidade} आधीच भरलेल्या आहेत. ते Excel मध्ये उघडा आणि Enable Editing वर क्लिक करा: स्प्रेडशीट तिचे आलेख, बेंचमार्क आणि संशयास्पद उत्तरे यांसह स्वतःच पुन्हा गणना करते.'),
  (gen_random_uuid()::text, 'mr', '7a7c53d439c4bf48', 'UEQ-S टॅब लहान आवृत्तीचे मूल्यमापन दाखवतो: व्यावहारिक, आनंददायी आणि एकूण गुणवत्ता, तिच्या बेंचमार्क आणि अधिकृत स्प्रेडशीटसह. UEQ-S अभ्यासात हाच संपूर्ण डॅशबोर्ड आहे; पूर्ण UEQ असलेल्या अभ्यासात तो UEQ-S च्या त्या 8 जोड्या वापरतो ज्यांना सहभागींनीही उत्तरे दिली.'),
  (gen_random_uuid()::text, 'mr', 'f1ae8e277add0379', 'अधिकृत डेटासेटशी तीच तुलना, पाच पातळ्यांत, उत्कृष्ट (सर्वोत्तम 10% मध्ये) पासून वाईट (सर्वात कमकुवत 25% मध्ये) पर्यंत. UEQ-S ची अधिकृत स्प्रेडशीट इशारा देते की लहान आवृत्तीचा अजून पुरेसा डेटा नाही: मर्यादा पूर्ण UEQ मधील त्याच 8 घटकांतून येतात आणि अंदाजे आहेत, त्यामुळे त्या काळजीपूर्वक वाचा.'),
  (gen_random_uuid()::text, 'mr', 'ce2f7def94215f23', '8 पैकी {iguais} घटकांत एकच स्थिती निवडली गेली{v}'),
  (gen_random_uuid()::text, 'mr', 'a7a4e2547797b3dc', 'लहान आवृत्तीचा अजून पुरेसा डेटा नाही: UEQ-S च्या मर्यादा पूर्ण UEQ मधील त्याच 8 घटकांतून येतात. पातळ्यांचा पहिला अंदाज म्हणून वापर करा.'),
