  (gen_random_uuid()::text, 'mr', '1e255e23d55c6fae', 'बहुतेक अभ्यासांत, उदा. उपयोगिता चाचणीनंतर'),
  (gen_random_uuid()::text, 'mr', 'c0d82be82fc68e75', 'पूर्ण UEQ असलेल्या अभ्यासात, निकाल वेगळ्या टॅबमध्ये UEQ-S देखील दाखवतात, जो त्याच्या 8 जोड्यांवरून मोजला जातो.'),
  (gen_random_uuid()::text, 'mr', '2b516db65a9ff8e6', 'पूर्ण UEQ मध्ये 26 जोड्या आहेत आणि तो 6 मापदंड मोजतो; बहुतेक अभ्यासांसाठी हाच सुचवला जातो. UEQ-S मध्ये यांपैकी 8 जोड्या आहेत, त्याला 1 ते 2 मिनिटे लागतात आणि तो फक्त व्यावहारिक गुणवत्ता, आनंददायी गुणवत्ता आणि एक एकूण गुण मोजतो; पूर्ण बसत नसेल तेव्हा तो वापरा. निवडीमुळे प्रश्नावली, डॅशबोर्ड आणि निर्यात केलेली स्प्रेडशीट बदलते, आणि पहिल्या उत्तरावर ती लॉक होते.'),
  (gen_random_uuid()::text, 'mr', 'aea48ff81a944c25', 'UEQ ची दोन रूपे आहेत. दोन्ही विरुद्ध शब्दांच्या त्याच जोड्या आणि 7 स्थितींचा तोच मापदंड वापरतात; लहान आवृत्ती 26 पैकी फक्त 8 जोड्या वापरते.'),
