  (gen_random_uuid()::text, 'mr', 'd37e05a5e11d0ce3', 'UEQ-S म्हणजे 26 पैकी 8 जोड्या: 11, 13, 20 आणि 21 (व्यावहारिक गुणवत्ता) आणि 6, 7, 10 आणि 15 (आनंददायी गुणवत्ता). हा टॅब या जोड्यांवरील सहभागींची उत्तरे त्याच पद्धतीने वापरतो ज्या पद्धतीने लेखकांनी UEQ-S आणि त्याचा बेंचमार्क तयार केला. 6 मापदंडांसाठी UEQ चे मापदंड टॅबवर परत जा.'),
  (gen_random_uuid()::text, 'mr', '6019d611a7d470f0', 'UEQ-S ही UEQ ची लहान आवृत्ती आहे: त्याच 26 पैकी 8 जोड्या, 7 स्थितींच्या त्याच मापदंडासह. तिला उत्तर देणे जलद आहे, पण ती 6 मापदंड वेगळे करत नाही. अभ्यास तयार करताना तुम्ही दोघांपैकी एक निवडता.'),
  (gen_random_uuid()::text, 'mr', 'bae875592e85a23c', 'अभ्यासात आधीच उत्तरे आहेत, त्यामुळे प्रश्नावली आता बदलता येत नाही. दुसरी वापरण्यासाठी नवीन अभ्यास तयार करा.'),
  (gen_random_uuid()::text, 'mr', '3b30696110490a7b', 'अधिकृत, 468 अभ्यासांतील 21,175 लोकांसह'),
