  (gen_random_uuid()::text, 'bn', '068ea3511e50f59a', 'UEQ-S-এর বেঞ্চমার্ক কী?'),
  (gen_random_uuid()::text, 'bn', 'e5b400d9a24d4f60', 'নেতিবাচক শব্দটি সব সময় বাঁ দিকে থাকে। প্রথম ৪টি ব্যবহারিক গুণমান মাপে; শেষ ৪টি আনন্দদায়ক গুণমান।'),
