  (gen_random_uuid()::text, 'bn', 'c9eb02e0f5cf4c07', 'ব্যবহারিক, আনন্দদায়ক ও সামগ্রিক গুণমানের n, গড়, মানক বিচ্যুতি, CI95, আলফা ও স্তর, সংস্করণ অনুযায়ী, শুধু বিশ্লেষণে থাকা অংশগ্রহণ নিয়ে।'),
  (gen_random_uuid()::text, 'bn', 'e6f8b54eeeb50370', 'ব্যবহারিক, আনন্দদায়ক ও সামগ্রিক গুণমানের n, গড়, মানক বিচ্যুতি, CI95, আলফা ও স্তর, সংস্করণ অনুযায়ী। কাঁচা উত্তরগুলো UEQ ট্যাব থেকে রপ্তানি হয়।'),
  (gen_random_uuid()::text, 'bn', 'af36e8d398f2f8b1', 'অংশগ্রহণকারী যে প্রশ্নাবলির উত্তর দেন, সম্মতিপত্রে জানানো সময়, ফলাফলের ড্যাশবোর্ড এবং আপনি যে অফিসিয়াল স্প্রেডশিট রপ্তানি করেন। UEQ-S-এ ৬টি স্কেল নেই: শুধু ব্যবহারিক গুণমান, আনন্দদায়ক গুণমান ও একটি সামগ্রিক স্কোর।'),
  (gen_random_uuid()::text, 'bn', 'e699fde816de1872', 'সবগুলো মাঝখানে'),
  (gen_random_uuid()::text, 'bn', '9c8ebeb323bd0fb0', 'এটি ৮টি আইটেমের গড়। হ্যান্ডবুক সতর্ক থাকতে বলে: এটি অভিজ্ঞতার একক সূচক নয়, কারণ ব্যবহারিক ও আনন্দদায়ক গুণমানের গুরুত্ব পণ্যভেদে আলাদা। এটি সব সময় দুটির সঙ্গে মিলিয়ে পড়ুন।'),
  (gen_random_uuid()::text, 'ta', 'a4079029268e4660', ', அனைத்தும் நடு நிலையில்.'),
