  (gen_random_uuid()::text, 'ta', 'b4d12aab565dedaa', '8 சொல் ஜோடிகள் · 1 முதல் 2 நிமிடங்கள்'),
  (gen_random_uuid()::text, 'ta', '3bd0b54b3c644bf9', '8, 26-இல் இருந்து எடுக்கப்பட்டவை'),
  (gen_random_uuid()::text, 'ta', '00bf7ea7a7150a2c', 'பதிப்பு {nome}-இன் பகுப்பாய்வில் உள்ள {quantidade} ஏற்கெனவே நிரப்பப்பட்ட UEQ-S Data Analysis Tool V15. அதை Excel-இல் திறந்து Enable Editing-ஐக் கிளிக் செய்யுங்கள்: விரிதாள் அதன் வரைபடங்கள், பெஞ்ச்மார்க் மற்றும் சந்தேகத்துக்குரிய பதில்களுடன் தானாகவே மீண்டும் கணக்கிடும்.'),
  (gen_random_uuid()::text, 'ta', 'f9150f74d9f74fe5', 'பகுப்பாய்வில் உள்ள {quantidade} ஏற்கெனவே நிரப்பப்பட்ட UEQ-S Data Analysis Tool V15. அதை Excel-இல் திறந்து Enable Editing-ஐக் கிளிக் செய்யுங்கள்: விரிதாள் அதன் வரைபடங்கள், பெஞ்ச்மார்க் மற்றும் சந்தேகத்துக்குரிய பதில்களுடன் தானாகவே மீண்டும் கணக்கிடும்.'),
  (gen_random_uuid()::text, 'ta', '7a7c53d439c4bf48', 'UEQ-S தாவல் குறுகிய பதிப்பின் மதிப்பீட்டைக் காட்டுகிறது: நடைமுறைத் தரம், இன்ப உணர்வுத் தரம் மற்றும் ஒட்டுமொத்தத் தரம், அதன் பெஞ்ச்மார்க் மற்றும் அதிகாரப்பூர்வ விரிதாளுடன். UEQ-S ஆய்வில் இதுவே முழு டாஷ்போர்டு; முழு UEQ ஆய்வில், பங்கேற்பாளர்கள் பதிலளித்த UEQ-S-இன் 8 ஜோடிகளை இது பயன்படுத்துகிறது.'),
  (gen_random_uuid()::text, 'ta', 'f1ae8e277add0379', 'அதிகாரப்பூர்வ தரவுத்தொகுப்புடன் அதே ஒப்பீடு, ஐந்து நிலைகளில், சிறப்பு (சிறந்த 10%-இல்) முதல் மோசம் (மிகக் குறைந்த 25%-இல்) வரை. குறுகிய பதிப்புக்கு இன்னும் போதுமான தரவு இல்லை என்று UEQ-S-இன் அதிகாரப்பூர்வ விரிதாள் எச்சரிக்கிறது: வரம்புகள் முழு UEQ-க்குள் உள்ள அதே 8 உருப்படிகளிலிருந்து வருகின்றன, அவை தோராயமானவை; கவனமாகப் படியுங்கள்.'),
  (gen_random_uuid()::text, 'ta', 'ce2f7def94215f23', '8 உருப்படிகளில் {iguais}-இல் ஒரே நிலை குறிக்கப்பட்டது{v}'),
  (gen_random_uuid()::text, 'ta', 'a7a4e2547797b3dc', 'குறுகிய பதிப்புக்கு இன்னும் போதுமான தரவு இல்லை: UEQ-S வரம்புகள் முழு UEQ-க்குள் உள்ள அதே 8 உருப்படிகளிலிருந்து வருகின்றன. நிலைகளை முதல் மதிப்பீடாகப் பயன்படுத்துங்கள்.'),
  (gen_random_uuid()::text, 'ta', 'ef299d5bbf1652c9', 'தோராயம்: வரம்புகள் இன்னும் முழு UEQ-க்குள் உள்ள அதே 8 உருப்படிகளிலிருந்து வருகின்றன'),
  (gen_random_uuid()::text, 'ta', 'ba3669e3ba121cc2', 'இரண்டு அளவுகோல்களும் முரண்பாடானவை, அல்லது 8 உருப்படிகளிலும் நடு நிலை ({meio})'),
  (gen_random_uuid()::text, 'ta', '04a4bec03d5421ad', '6 அளவுகோல்கள், அவற்றிலிருந்து நடைமுறைத் தரமும் இன்ப உணர்வுத் தரமும்'),
  (gen_random_uuid()::text, 'ta', 'ff1816b44eeac188', 'முதல் பதில் வந்தவுடன் நடைமுறை, இன்ப உணர்வு மற்றும் ஒட்டுமொத்தத் தரத்தின் சராசரிகள், நம்பக இடைவெளிகள், ஆல்ஃபா, பெஞ்ச்மார்க் இங்கே தோன்றும்.'),
  (gen_random_uuid()::text, 'ta', '8362db625cf11792', 'தோராயமான பெஞ்ச்மார்க்.'),
  (gen_random_uuid()::text, 'ta', '4ec93dc43d6943cf', 'ஒவ்வொரு புள்ளியும் ஜோடிக்கான பதில்களின் சராசரி, இடது சொல்லிலிருந்து (-3) வலது சொல் (+3) வரை. UEQ-S-இல் எதிர்மறைச் சொல் எப்போதும் இடதுபுறம் இருக்கும்.'),
  (gen_random_uuid()::text, 'ta', 'd4679986e4a13fa2', 'ஒட்டுமொத்த அளவுகோலை எப்படிப் படிப்பது?'),
  (gen_random_uuid()::text, 'ta', '15900c5ffe6b043b', '1 முதல் 2 நிமிடங்கள்'),
  (gen_random_uuid()::text, 'ta', 'd84a57665a63d405', '1 முதல் 2 நிமிடங்கள் · தன்னார்வமானது, அடையாளமற்றது'),
  (gen_random_uuid()::text, 'ta', '56deeeb5cd215073', '2 முதல் 3 நிமிடங்கள் · தன்னார்வமானது, அடையாளமற்றது'),
  (gen_random_uuid()::text, 'ta', '6299af052f4defd9', '3 முதல் 5 நிமிடங்கள்'),
  (gen_random_uuid()::text, 'ta', 'f426d43aed1aae02', 'முதல் பதிலுக்குப் பிறகு தேர்வு பூட்டப்படும், அதனால் ஆய்வு இரண்டு கேள்வித்தாள்களையும் கலக்காது.'),
  (gen_random_uuid()::text, 'ta', '2a804d05f2c8bc31', 'முழு UEQ-க்கும் UEQ-S-க்கும் உள்ள வேறுபாடுகள்'),
  (gen_random_uuid()::text, 'ta', '1c3de5d03a2c189d', 'UEQ-S அளவுகோல்கள்'),
  (gen_random_uuid()::text, 'ta', 'b2fdc6cdf7a4e017', 'கேள்வித்தாளைத் தேர்ந்தெடுங்கள்: முழு UEQ அல்லது UEQ-S.'),
  (gen_random_uuid()::text, 'ta', 'b50ee17343aec113', 'UEQ-S ஆய்வு'),
  (gen_random_uuid()::text, 'ta', '51658f25775c996d', 'Ferramenta UEQ · UEQ-S முடிவுகள் டாஷ்போர்டு'),
  (gen_random_uuid()::text, 'ta', 'f1d3445f45dc3300', 'ஒட்டுமொத்தம்'),
  (gen_random_uuid()::text, 'ta', '3b297def8e05630a', 'உருப்படி {numero}: {esquerdo} முதல் {direito} வரை'),
  (gen_random_uuid()::text, 'ta', '98f022d65a10c65c', 'உருப்படிகள் 1 முதல் 4'),
  (gen_random_uuid()::text, 'ta', 'adcce322242c323d', 'உருப்படிகள் 5 முதல் 8'),
  (gen_random_uuid()::text, 'ta', 'dd339111f097feb6', '6 அளவுகோல்களையும் (ஈர்ப்பு, தெளிவு, திறன், நம்பகத்தன்மை, தூண்டல், புதுமை) அவற்றிலிருந்து நடைமுறைத் தரத்தையும் இன்ப உணர்வுத் தரத்தையும் அளக்கிறது. பெரும்பாலான ஆய்வுகளுக்கு இதுவே பரிந்துரைக்கப்படுகிறது, எ.கா. பயன்பாட்டுச் சோதனைக்குப் பிறகு.'),
  (gen_random_uuid()::text, 'ta', 'a61910ac3ff95713', 'நடைமுறைத் தரம், இன்ப உணர்வுத் தரம், ஒரு ஒட்டுமொத்த மதிப்பெண் மட்டுமே அளக்கிறது, 6 அளவுகோல்கள் இல்லாமல். முழுமையானது பொருந்தாதபோது: குறைந்த நேரம், நீண்ட கேள்வித்தாளுக்குள் UEQ, அல்லது ஒரே நபர் பல தயாரிப்புகளைத் தொடர்ந்து மதிப்பிடுவது.'),
  (gen_random_uuid()::text, 'ta', '8597715d8249479a', 'அதே வடிவம், -3 முதல் +3 வரையிலான மதிப்புகளுடன். UEQ-S-இல் நேர்மறைச் சொல் எப்போதும் வலதுபுறம் இருக்கும்.'),
  (gen_random_uuid()::text, 'ta', 'dd96696d8f635d25', '95% நம்பக இடைவெளி மற்றும் பெஞ்ச்மார்க் நிலைகளுடன் UEQ-S-இன் மூன்று அளவுகோல்களின் சராசரிகள்.'),
  (gen_random_uuid()::text, 'ta', '1e255e23d55c6fae', 'பெரும்பாலான ஆய்வுகளில், எ.கா. பயன்பாட்டுச் சோதனைக்குப் பிறகு'),
  (gen_random_uuid()::text, 'ta', 'c0d82be82fc68e75', 'முழு UEQ ஆய்வில், முடிவுகள் தனி தாவலில் UEQ-S-ஐயும் காட்டுகின்றன, அதன் 8 ஜோடிகளிலிருந்து கணக்கிடப்பட்டது.'),
  (gen_random_uuid()::text, 'ta', '2b516db65a9ff8e6', 'முழு UEQ-இல் 26 ஜோடிகள் உள்ளன, அது 6 அளவுகோல்களை அளக்கிறது; பெரும்பாலான ஆய்வுகளுக்கு இதுவே பரிந்துரைக்கப்படுகிறது. UEQ-S-இல் அவற்றில் 8 ஜோடிகள் உள்ளன, அதற்கு 1 முதல் 2 நிமிடங்கள் ஆகும், அது நடைமுறைத் தரம், இன்ப உணர்வுத் தரம், ஒரு ஒட்டுமொத்த மதிப்பெண் மட்டுமே அளக்கிறது; முழுமையானது பொருந்தாதபோது இதைப் பயன்படுத்துங்கள். தேர்வு கேள்வித்தாள், டாஷ்போர்டு, ஏற்றுமதி செய்யப்படும் விரிதாள் ஆகியவற்றை மாற்றுகிறது; முதல் பதிலில் பூட்டப்படுகிறது.'),
  (gen_random_uuid()::text, 'ta', 'aea48ff81a944c25', 'UEQ-க்கு இரண்டு வடிவங்கள் உள்ளன. இரண்டும் எதிர்ச்சொற்களின் அதே ஜோடிகளையும் 7 நிலைகள் கொண்ட அதே அளவுகோலையும் பயன்படுத்துகின்றன; குறுகிய பதிப்பு 26-இல் 8 ஜோடிகளை மட்டுமே பயன்படுத்துகிறது.'),
  (gen_random_uuid()::text, 'ta', '6d0c31c3f5025db1', 'முழு UEQ-இலிருந்து UEQ-S.'),
  (gen_random_uuid()::text, 'ta', 'd37e05a5e11d0ce3', 'UEQ-S என்பது 26-இல் 8 ஜோடிகள்: 11, 13, 20, 21 (நடைமுறைத் தரம்) மற்றும் 6, 7, 10, 15 (இன்ப உணர்வுத் தரம்). ஆசிரியர்கள் UEQ-S-ஐயும் அதன் பெஞ்ச்மார்க்கையும் உருவாக்கிய அதே வழியில், இந்த ஜோடிகளுக்குப் பங்கேற்பாளர்கள் அளித்த பதில்களை இந்தத் தாவல் பயன்படுத்துகிறது. 6 அளவுகோல்களுக்கு, UEQ அளவுகோல்கள் தாவலுக்குத் திரும்புங்கள்.'),
  (gen_random_uuid()::text, 'ta', '6019d611a7d470f0', 'UEQ-S என்பது UEQ-இன் குறுகிய பதிப்பு: அதே 26-இல் 8 ஜோடிகள், 7 நிலைகள் கொண்ட அதே அளவுகோலுடன். இதற்குப் பதிலளிப்பது விரைவானது, ஆனால் இது 6 அளவுகோல்களைப் பிரிப்பதில்லை. ஆய்வை உருவாக்கும்போது இரண்டில் ஒன்றைத் தேர்ந்தெடுக்கிறீர்கள்.'),
  (gen_random_uuid()::text, 'ta', 'bae875592e85a23c', 'ஆய்வில் ஏற்கெனவே பதில்கள் உள்ளன, எனவே கேள்வித்தாளை இனி மாற்ற முடியாது. மற்றொன்றைப் பயன்படுத்த, புதிய ஆய்வை உருவாக்குங்கள்.'),
  (gen_random_uuid()::text, 'ta', '3b30696110490a7b', 'அதிகாரப்பூர்வமானது, 468 ஆய்வுகளின் 21,175 பேருடன்'),
  (gen_random_uuid()::text, 'ta', 'e124308087e6e9c0', 'இது எதை அளக்கிறது'),
  (gen_random_uuid()::text, 'ta', '42f77b4043940783', 'தேர்வு எதை மாற்றுகிறது:'),
  (gen_random_uuid()::text, 'ta', '3c3472b75b92e9b3', 'நடைமுறைத் தரமும் இன்ப உணர்வுத் தரமும் என்ன?'),
  (gen_random_uuid()::text, 'ta', '068ea3511e50f59a', 'UEQ-S-இன் பெஞ்ச்மார்க் என்ன?'),
  (gen_random_uuid()::text, 'ta', 'e5b400d9a24d4f60', 'எதிர்மறைச் சொல் எப்போதும் இடதுபுறம் இருக்கும். முதல் 4 நடைமுறைத் தரத்தையும், கடைசி 4 இன்ப உணர்வுத் தரத்தையும் அளக்கின்றன.'),
  (gen_random_uuid()::text, 'ta', '9a4e71736bd04c92', '8 உருப்படிகள்'),
  (gen_random_uuid()::text, 'ta', '6b693fdd2d2678f8', 'UEQ-S-இன் 8 ஜோடிகள்'),
  (gen_random_uuid()::text, 'ta', '38be6e60ef6b0b1c', 'சொல் ஜோடிகள்'),
  (gen_random_uuid()::text, 'ta', 'e24b06506e99c6d1', 'UEQ-S அதிகாரப்பூர்வ விரிதாள் (XLSX)'),
  (gen_random_uuid()::text, 'ta', 'ad046c0476e87fed', 'UEQ-S அதிகாரப்பூர்வ விரிதாள் மற்றும் data/protocolo-ueq-s.json'),
  (gen_random_uuid()::text, 'ta', 'a714567f4023225f', 'ஏற்றுமதி செய்யப்படும் அதிகாரப்பூர்வ விரிதாள்'),
  (gen_random_uuid()::text, 'ta', '85813aa17fb73bf5', 'நடைமுறை என்பது, ஒருவருக்குத் தேவையானதைச் செய்யத் தயாரிப்பு உதவுகிறதா என்பது: உருப்படிகள் 1 முதல் 4 (ஆதரவு, எளிமை, திறன், தெளிவு). இன்ப உணர்வு என்பது, பயன்படுத்துவது இனிமையாகவும் சுவாரசியமாகவும் உள்ளதா என்பது: உருப்படிகள் 5 முதல் 8 (உற்சாகமூட்டும், சுவாரசியமான, புதுமையான, முன்னோடியான). UEQ-S முழு UEQ-இன் 6 அளவுகோல்களைப் பிரிப்பதில்லை.'),
  (gen_random_uuid()::text, 'ta', 'ef0e1e29b2f962d8', 'முழுமையானது பொருந்தாதபோது: குறைந்த நேரம், நீண்ட கேள்வித்தாளுக்குள் UEQ, அல்லது ஒரே நபர் பல தயாரிப்புகளைத் தொடர்ந்து மதிப்பிடுவது'),
  (gen_random_uuid()::text, 'ta', '1cca5e91e7af19e4', 'எப்போது பயன்படுத்துவது'),
  (gen_random_uuid()::text, 'ta', '7f9e52e1d71739db', 'கேள்வித்தாள்'),
  (gen_random_uuid()::text, 'ta', '58fd4e45864dabe5', 'ஆய்வின் கேள்வித்தாள்'),
  (gen_random_uuid()::text, 'ta', '14840a1d0ddcfedc', 'கேள்வித்தாள்: UEQ அல்லது UEQ-S'),
  (gen_random_uuid()::text, 'ta', '773e4c885727a324', 'அளவுகோல் வாரியாக UEQ-S முடிவுகள் (CSV)'),
  (gen_random_uuid()::text, 'ta', '729142a8a48c4260', 'ஆய்வு UEQ-S-ஐப் பயன்படுத்தினால், CSV-இல் UEQ-S வரிசையில் 8 நெடுவரிசைகள் இருக்கும், UEQ-S அதிகாரப்பூர்வ விரிதாளின் Data தாளில் உள்ளதுபோல.'),
  (gen_random_uuid()::text, 'ta', '9cdfdcbc7651d71c', 'நடைமுறைத் தரம், இன்ப உணர்வுத் தரம், ஒரு ஒட்டுமொத்த மதிப்பெண் மட்டும்'),
  (gen_random_uuid()::text, 'ta', 'b34e5952b4b2083e', 'பதிலளிக்கும் நேரம்'),
  (gen_random_uuid()::text, 'ta', 'fbdd1e04c28b7a98', 'முழு UEQ'),
  (gen_random_uuid()::text, 'ta', '610ae398d878994a', 'UEQ அல்லது UEQ-S'),
  (gen_random_uuid()::text, 'ta', '9e528d7c059e370e', 'UEQ-S · {titulo} · Ferramenta UEQ'),
  (gen_random_uuid()::text, 'ta', '1b445fb03d286686', 'UEQ-S, குறுகிய பதிப்பு'),
  (gen_random_uuid()::text, 'ta', '144bff43d73703cd', 'UEQ-S, குறுகிய பதிப்பு · 8 உருப்படிகள் · {length} மொழிகள்'),
  (gen_random_uuid()::text, 'ta', '0047e4cd8189b5b1', 'ஒவ்வொரு பங்கேற்புக்கும் ஒரு வரிசை, UEQ-S வரிசையில் 1 முதல் 7 வரையிலான 8 மதிப்புகள், பகுப்பாய்வில் சேர்ப்பு மற்றும் சந்தேக நெடுவரிசைகளுடன்.'),
  (gen_random_uuid()::text, 'ta', '05daef7262999aa0', 'ஒரு வரிசைக்கு ஒருவர், UEQ-S வரிசையில் 1 முதல் 7 வரையிலான 8 மதிப்புகள், தலைப்பு இல்லாமல், UEQ-S அதிகாரப்பூர்வ விரிதாளின் Data தாளில் உள்ளதுபோல. அரைப்புள்ளி, காற்புள்ளி அல்லது தாவலால் பிரிக்கப்பட்டவை. அதிகபட்சம் 5000 வரிசைகள்.'),
  (gen_random_uuid()::text, 'ta', '72786137971549ab', 'UEQ-க்கும் UEQ-S-க்கும் உள்ள வேறுபாட்டைப் பாருங்கள்'),
  (gen_random_uuid()::text, 'ta', 'c9eb02e0f5cf4c07', 'நடைமுறை, இன்ப உணர்வு மற்றும் ஒட்டுமொத்தத் தரத்தின் n, சராசரி, திட்டவிலக்கம், CI95, ஆல்ஃபா, நிலைகள், பதிப்பு வாரியாக, பகுப்பாய்வில் உள்ள பங்கேற்புகளுடன் மட்டும்.'),
  (gen_random_uuid()::text, 'ta', 'e6f8b54eeeb50370', 'நடைமுறை, இன்ப உணர்வு மற்றும் ஒட்டுமொத்தத் தரத்தின் n, சராசரி, திட்டவிலக்கம், CI95, ஆல்ஃபா, நிலைகள், பதிப்பு வாரியாக. மூலப் பதில்கள் UEQ தாவலில் இருந்து ஏற்றுமதி செய்யப்படுகின்றன.'),
  (gen_random_uuid()::text, 'ta', 'af36e8d398f2f8b1', 'பங்கேற்பாளர் பதிலளிக்கும் கேள்வித்தாள், ஒப்புதலில் குறிப்பிடப்படும் நேரம், முடிவுகள் டாஷ்போர்டு, நீங்கள் ஏற்றுமதி செய்யும் அதிகாரப்பூர்வ விரிதாள். UEQ-S-இல் 6 அளவுகோல்கள் இல்லை: நடைமுறைத் தரம், இன்ப உணர்வுத் தரம், ஒரு ஒட்டுமொத்த மதிப்பெண் மட்டுமே.'),
  (gen_random_uuid()::text, 'ta', 'e699fde816de1872', 'அனைத்தும் நடுவில்'),
  (gen_random_uuid()::text, 'ta', '9c8ebeb323bd0fb0', 'இது 8 உருப்படிகளின் சராசரி. கையேடு கவனமாக இருக்கச் சொல்கிறது: இது அனுபவத்தின் ஒற்றைக் குறிகாட்டி அல்ல, ஏனெனில் நடைமுறைத் தரம் மற்றும் இன்ப உணர்வுத் தரத்தின் முக்கியத்துவம் தயாரிப்புக்குத் தயாரிப்பு மாறுபடும். இதை எப்போதும் அவ்விரண்டுடன் சேர்த்துப் படியுங்கள்.'),
  (gen_random_uuid()::text, 'kn', 'a4079029268e4660', ', ಎಲ್ಲವೂ ಮಧ್ಯದ ಸ್ಥಾನದಲ್ಲಿ.'),
  (gen_random_uuid()::text, 'kn', '0b1c60f0d880a91c', '26 ಪದಜೋಡಿಗಳು · 3 ರಿಂದ 5 ನಿಮಿಷಗಳು'),
  (gen_random_uuid()::text, 'kn', 'b4d12aab565dedaa', '8 ಪದಜೋಡಿಗಳು · 1 ರಿಂದ 2 ನಿಮಿಷಗಳು'),
  (gen_random_uuid()::text, 'kn', '3bd0b54b3c644bf9', '8, 26 ರಲ್ಲಿ ಆಯ್ದವು'),
  (gen_random_uuid()::text, 'kn', '00bf7ea7a7150a2c', 'ಆವೃತ್ತಿ {nome} ಯ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿರುವ {quantidade} ಈಗಾಗಲೇ ತುಂಬಿರುವ UEQ-S Data Analysis Tool V15. ಅದನ್ನು Excel ನಲ್ಲಿ ತೆರೆದು Enable Editing ಕ್ಲಿಕ್ ಮಾಡಿ: ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ತನ್ನ ಚಾರ್ಟ್‌ಗಳು, ಬೆಂಚ್‌ಮಾರ್ಕ್ ಮತ್ತು ಸಂಶಯಾಸ್ಪದ ಉತ್ತರಗಳೊಂದಿಗೆ ತಾನೇ ಮರುಲೆಕ್ಕ ಮಾಡುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'kn', 'f9150f74d9f74fe5', 'ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿರುವ {quantidade} ಈಗಾಗಲೇ ತುಂಬಿರುವ UEQ-S Data Analysis Tool V15. ಅದನ್ನು Excel ನಲ್ಲಿ ತೆರೆದು Enable Editing ಕ್ಲಿಕ್ ಮಾಡಿ: ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ತನ್ನ ಚಾರ್ಟ್‌ಗಳು, ಬೆಂಚ್‌ಮಾರ್ಕ್ ಮತ್ತು ಸಂಶಯಾಸ್ಪದ ಉತ್ತರಗಳೊಂದಿಗೆ ತಾನೇ ಮರುಲೆಕ್ಕ ಮಾಡುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'kn', '7a7c53d439c4bf48', 'UEQ-S ಟ್ಯಾಬ್ ಚಿಕ್ಕ ಆವೃತ್ತಿಯ ಮೌಲ್ಯಮಾಪನವನ್ನು ತೋರಿಸುತ್ತದೆ: ಪ್ರಾಯೋಗಿಕ, ಹೆಡೋನಿಕ್ ಮತ್ತು ಒಟ್ಟಾರೆ ಗುಣಮಟ್ಟ, ಅದರ ಬೆಂಚ್‌ಮಾರ್ಕ್ ಮತ್ತು ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ನೊಂದಿಗೆ. UEQ-S ಅಧ್ಯಯನದಲ್ಲಿ ಇದೇ ಸಂಪೂರ್ಣ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್; ಪೂರ್ಣ UEQ ಅಧ್ಯಯನದಲ್ಲಿ, ಭಾಗವಹಿಸುವವರು ಉತ್ತರಿಸಿದ UEQ-S ನ 8 ಜೋಡಿಗಳನ್ನು ಇದು ಬಳಸುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'kn', 'f1ae8e277add0379', 'ಅಧಿಕೃತ ದತ್ತಾಂಶದೊಂದಿಗೆ ಅದೇ ಹೋಲಿಕೆ, ಐದು ಹಂತಗಳಲ್ಲಿ, ಅತ್ಯುತ್ತಮ (ಅತ್ಯುತ್ತಮ 10% ರೊಳಗೆ) ದಿಂದ ಕಳಪೆ (ಅತಿ ದುರ್ಬಲ 25% ರೊಳಗೆ) ವರೆಗೆ. ಚಿಕ್ಕ ಆವೃತ್ತಿಗೆ ಇನ್ನೂ ಸಾಕಷ್ಟು ದತ್ತಾಂಶವಿಲ್ಲ ಎಂದು UEQ-S ನ ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಎಚ್ಚರಿಸುತ್ತದೆ: ಮಿತಿಗಳು ಪೂರ್ಣ UEQ ಒಳಗಿನ ಅದೇ 8 ಅಂಶಗಳಿಂದ ಬರುತ್ತವೆ ಮತ್ತು ಅಂದಾಜು; ಎಚ್ಚರಿಕೆಯಿಂದ ಓದಿ.'),
  (gen_random_uuid()::text, 'kn', 'ce2f7def94215f23', '8 ಅಂಶಗಳಲ್ಲಿ {iguais} ರಲ್ಲಿ ಒಂದೇ ಸ್ಥಾನವನ್ನು ಗುರುತಿಸಲಾಗಿದೆ{v}'),
  (gen_random_uuid()::text, 'kn', 'a7a4e2547797b3dc', 'ಚಿಕ್ಕ ಆವೃತ್ತಿಗೆ ಇನ್ನೂ ಸಾಕಷ್ಟು ದತ್ತಾಂಶವಿಲ್ಲ: UEQ-S ಮಿತಿಗಳು ಪೂರ್ಣ UEQ ಒಳಗಿನ ಅದೇ 8 ಅಂಶಗಳಿಂದ ಬರುತ್ತವೆ. ಹಂತಗಳನ್ನು ಮೊದಲ ಅಂದಾಜಾಗಿ ಬಳಸಿ.'),
  (gen_random_uuid()::text, 'kn', 'ef299d5bbf1652c9', 'ಅಂದಾಜು: ಮಿತಿಗಳು ಇನ್ನೂ ಪೂರ್ಣ UEQ ಒಳಗಿನ ಅದೇ 8 ಅಂಶಗಳಿಂದ ಬರುತ್ತವೆ'),
  (gen_random_uuid()::text, 'kn', 'ba3669e3ba121cc2', 'ಎರಡೂ ಮಾಪಕಗಳು ಅಸಂಗತ, ಅಥವಾ ಎಲ್ಲಾ 8 ಅಂಶಗಳಲ್ಲಿ ಮಧ್ಯದ ಸ್ಥಾನ ({meio})'),
  (gen_random_uuid()::text, 'kn', '04a4bec03d5421ad', '6 ಮಾಪಕಗಳು ಮತ್ತು ಅವುಗಳಿಂದ ಪ್ರಾಯೋಗಿಕ ಹಾಗೂ ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟ'),
  (gen_random_uuid()::text, 'kn', 'ff1816b44eeac188', 'ಮೊದಲ ಉತ್ತರ ಬಂದ ತಕ್ಷಣ ಪ್ರಾಯೋಗಿಕ, ಹೆಡೋನಿಕ್ ಮತ್ತು ಒಟ್ಟಾರೆ ಗುಣಮಟ್ಟದ ಸರಾಸರಿಗಳು, ವಿಶ್ವಾಸ ಅಂತರಗಳು, ಆಲ್ಫಾ ಮತ್ತು ಬೆಂಚ್‌ಮಾರ್ಕ್ ಇಲ್ಲಿ ಕಾಣಿಸುತ್ತವೆ.'),
  (gen_random_uuid()::text, 'kn', '8362db625cf11792', 'ಅಂದಾಜು ಬೆಂಚ್‌ಮಾರ್ಕ್.'),
  (gen_random_uuid()::text, 'kn', '4ec93dc43d6943cf', 'ಪ್ರತಿ ಬಿಂದುವೂ ಜೋಡಿಗೆ ನೀಡಿದ ಉತ್ತರಗಳ ಸರಾಸರಿ, ಎಡ ಪದದಿಂದ (-3) ಬಲ ಪದದವರೆಗೆ (+3). UEQ-S ನಲ್ಲಿ ನಕಾರಾತ್ಮಕ ಪದ ಯಾವಾಗಲೂ ಎಡಭಾಗದಲ್ಲಿರುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'kn', 'd4679986e4a13fa2', 'ಒಟ್ಟಾರೆ ಮಾಪಕವನ್ನು ಹೇಗೆ ಓದುವುದು?'),
  (gen_random_uuid()::text, 'kn', '15900c5ffe6b043b', '1 ರಿಂದ 2 ನಿಮಿಷಗಳು'),
  (gen_random_uuid()::text, 'kn', 'd84a57665a63d405', '1 ರಿಂದ 2 ನಿಮಿಷಗಳು · ಸ್ವಯಂಪ್ರೇರಿತ ಮತ್ತು ಅನಾಮಧೇಯ'),
  (gen_random_uuid()::text, 'kn', '56deeeb5cd215073', '2 ರಿಂದ 3 ನಿಮಿಷಗಳು · ಸ್ವಯಂಪ್ರೇರಿತ ಮತ್ತು ಅನಾಮಧೇಯ'),
  (gen_random_uuid()::text, 'kn', '6299af052f4defd9', '3 ರಿಂದ 5 ನಿಮಿಷಗಳು'),
  (gen_random_uuid()::text, 'kn', 'f426d43aed1aae02', 'ಮೊದಲ ಉತ್ತರದ ನಂತರ ಆಯ್ಕೆ ಲಾಕ್ ಆಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಅಧ್ಯಯನವು ಎರಡು ಪ್ರಶ್ನಾವಳಿಗಳನ್ನು ಬೆರೆಸುವುದಿಲ್ಲ.'),
  (gen_random_uuid()::text, 'kn', '2a804d05f2c8bc31', 'ಪೂರ್ಣ UEQ ಮತ್ತು UEQ-S ನಡುವಿನ ವ್ಯತ್ಯಾಸಗಳು'),
  (gen_random_uuid()::text, 'kn', '1c3de5d03a2c189d', 'UEQ-S ಮಾಪಕಗಳು'),
  (gen_random_uuid()::text, 'kn', 'b2fdc6cdf7a4e017', 'ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಆಯ್ಕೆಮಾಡಿ: ಪೂರ್ಣ UEQ ಅಥವಾ UEQ-S.'),
  (gen_random_uuid()::text, 'kn', 'b50ee17343aec113', 'UEQ-S ಅಧ್ಯಯನ'),
  (gen_random_uuid()::text, 'kn', '51658f25775c996d', 'Ferramenta UEQ · UEQ-S ಫಲಿತಾಂಶಗಳ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್'),
  (gen_random_uuid()::text, 'kn', 'f1d3445f45dc3300', 'ಒಟ್ಟಾರೆ'),
  (gen_random_uuid()::text, 'kn', '3b297def8e05630a', 'ಅಂಶ {numero}: {esquerdo} ರಿಂದ {direito} ವರೆಗೆ'),
  (gen_random_uuid()::text, 'kn', '98f022d65a10c65c', 'ಅಂಶಗಳು 1 ರಿಂದ 4'),
  (gen_random_uuid()::text, 'kn', 'adcce322242c323d', 'ಅಂಶಗಳು 5 ರಿಂದ 8'),
  (gen_random_uuid()::text, 'kn', 'dd339111f097feb6', '6 ಮಾಪಕಗಳನ್ನು (ಆಕರ್ಷಣೆ, ಸ್ಪಷ್ಟತೆ, ದಕ್ಷತೆ, ವಿಶ್ವಾಸಾರ್ಹತೆ, ಪ್ರಚೋದನೆ ಮತ್ತು ನವೀನತೆ) ಹಾಗೂ ಅವುಗಳಿಂದ ಪ್ರಾಯೋಗಿಕ ಮತ್ತು ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟವನ್ನು ಅಳೆಯುತ್ತದೆ. ಹೆಚ್ಚಿನ ಅಧ್ಯಯನಗಳಿಗೆ ಇದನ್ನೇ ಶಿಫಾರಸು ಮಾಡಲಾಗುತ್ತದೆ, ಉದಾ. ಉಪಯುಕ್ತತಾ ಪರೀಕ್ಷೆಯ ನಂತರ.'),
  (gen_random_uuid()::text, 'kn', 'a61910ac3ff95713', 'ಪ್ರಾಯೋಗಿಕ ಗುಣಮಟ್ಟ, ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟ ಮತ್ತು ಒಂದು ಒಟ್ಟಾರೆ ಅಂಕವನ್ನು ಮಾತ್ರ ಅಳೆಯುತ್ತದೆ, 6 ಮಾಪಕಗಳಿಲ್ಲದೆ. ಪೂರ್ಣ ಪ್ರಶ್ನಾವಳಿ ಹೊಂದದಿದ್ದಾಗ: ಕಡಿಮೆ ಸಮಯ, ದೀರ್ಘ ಪ್ರಶ್ನಾವಳಿಯೊಳಗೆ UEQ, ಅಥವಾ ಒಬ್ಬನೇ ವ್ಯಕ್ತಿ ಹಲವು ಉತ್ಪನ್ನಗಳನ್ನು ಸತತವಾಗಿ ಮೌಲ್ಯಮಾಪನ ಮಾಡುವುದು.'),
  (gen_random_uuid()::text, 'kn', '8597715d8249479a', 'ಅದೇ ಸ್ವರೂಪ, -3 ರಿಂದ +3 ಮೌಲ್ಯಗಳೊಂದಿಗೆ. UEQ-S ನಲ್ಲಿ ಸಕಾರಾತ್ಮಕ ಪದ ಯಾವಾಗಲೂ ಬಲಭಾಗದಲ್ಲಿರುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'kn', 'dd96696d8f635d25', '95% ವಿಶ್ವಾಸ ಅಂತರ ಮತ್ತು ಬೆಂಚ್‌ಮಾರ್ಕ್ ಹಂತಗಳೊಂದಿಗೆ UEQ-S ನ ಮೂರು ಮಾಪಕಗಳ ಸರಾಸರಿಗಳು.'),
  (gen_random_uuid()::text, 'kn', '1e255e23d55c6fae', 'ಹೆಚ್ಚಿನ ಅಧ್ಯಯನಗಳಲ್ಲಿ, ಉದಾ. ಉಪಯುಕ್ತತಾ ಪರೀಕ್ಷೆಯ ನಂತರ'),
  (gen_random_uuid()::text, 'kn', 'c0d82be82fc68e75', 'ಪೂರ್ಣ UEQ ಅಧ್ಯಯನದಲ್ಲಿ, ಫಲಿತಾಂಶಗಳು ಪ್ರತ್ಯೇಕ ಟ್ಯಾಬ್‌ನಲ್ಲಿ UEQ-S ಅನ್ನೂ ತೋರಿಸುತ್ತವೆ, ಅದರ 8 ಜೋಡಿಗಳಿಂದ ಲೆಕ್ಕಹಾಕಲಾಗಿದೆ.'),
  (gen_random_uuid()::text, 'kn', '2b516db65a9ff8e6', 'ಪೂರ್ಣ UEQ ನಲ್ಲಿ 26 ಜೋಡಿಗಳಿವೆ ಮತ್ತು ಅದು 6 ಮಾಪಕಗಳನ್ನು ಅಳೆಯುತ್ತದೆ; ಹೆಚ್ಚಿನ ಅಧ್ಯಯನಗಳಿಗೆ ಇದನ್ನೇ ಶಿಫಾರಸು ಮಾಡಲಾಗುತ್ತದೆ. UEQ-S ನಲ್ಲಿ ಇವುಗಳಲ್ಲಿ 8 ಜೋಡಿಗಳಿವೆ, ಇದಕ್ಕೆ 1 ರಿಂದ 2 ನಿಮಿಷಗಳು ಬೇಕು ಮತ್ತು ಇದು ಪ್ರಾಯೋಗಿಕ ಗುಣಮಟ್ಟ, ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟ ಮತ್ತು ಒಂದು ಒಟ್ಟಾರೆ ಅಂಕವನ್ನು ಮಾತ್ರ ಅಳೆಯುತ್ತದೆ; ಪೂರ್ಣವು ಹೊಂದದಿದ್ದಾಗ ಇದನ್ನು ಬಳಸಿ. ಆಯ್ಕೆಯು ಪ್ರಶ್ನಾವಳಿ, ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಮತ್ತು ರಫ್ತು ಮಾಡಿದ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಅನ್ನು ಬದಲಾಯಿಸುತ್ತದೆ ಮತ್ತು ಮೊದಲ ಉತ್ತರದೊಂದಿಗೆ ಲಾಕ್ ಆಗುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'kn', 'aea48ff81a944c25', 'UEQ ಗೆ ಎರಡು ರೂಪಗಳಿವೆ. ಎರಡೂ ವಿರುದ್ಧ ಪದಗಳ ಅದೇ ಜೋಡಿಗಳನ್ನು ಮತ್ತು 7 ಸ್ಥಾನಗಳ ಅದೇ ಮಾಪಕವನ್ನು ಬಳಸುತ್ತವೆ; ಚಿಕ್ಕ ಆವೃತ್ತಿ 26 ರಲ್ಲಿ 8 ಜೋಡಿಗಳನ್ನು ಮಾತ್ರ ಬಳಸುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'kn', '6d0c31c3f5025db1', 'ಪೂರ್ಣ UEQ ನಿಂದ UEQ-S.'),
  (gen_random_uuid()::text, 'kn', 'd37e05a5e11d0ce3', 'UEQ-S ಎಂದರೆ 26 ರಲ್ಲಿ 8 ಜೋಡಿಗಳು: 11, 13, 20 ಮತ್ತು 21 (ಪ್ರಾಯೋಗಿಕ ಗುಣಮಟ್ಟ) ಹಾಗೂ 6, 7, 10 ಮತ್ತು 15 (ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟ). ಲೇಖಕರು UEQ-S ಮತ್ತು ಅದರ ಬೆಂಚ್‌ಮಾರ್ಕ್ ಅನ್ನು ರೂಪಿಸಿದ ರೀತಿಯಲ್ಲೇ, ಈ ಜೋಡಿಗಳಿಗೆ ಭಾಗವಹಿಸುವವರು ನೀಡಿದ ಉತ್ತರಗಳನ್ನು ಈ ಟ್ಯಾಬ್ ಬಳಸುತ್ತದೆ. 6 ಮಾಪಕಗಳಿಗಾಗಿ UEQ ಮಾಪಕಗಳು ಟ್ಯಾಬ್‌ಗೆ ಹಿಂತಿರುಗಿ.'),
  (gen_random_uuid()::text, 'kn', '6019d611a7d470f0', 'UEQ-S ಎಂಬುದು UEQ ನ ಚಿಕ್ಕ ಆವೃತ್ತಿ: ಅದೇ 26 ರಲ್ಲಿ 8 ಜೋಡಿಗಳು, 7 ಸ್ಥಾನಗಳ ಅದೇ ಮಾಪಕದೊಂದಿಗೆ. ಇದಕ್ಕೆ ಉತ್ತರಿಸುವುದು ವೇಗವಾಗಿದೆ, ಆದರೆ ಇದು 6 ಮಾಪಕಗಳನ್ನು ಬೇರ್ಪಡಿಸುವುದಿಲ್ಲ. ಅಧ್ಯಯನ ರಚಿಸುವಾಗ ನೀವು ಎರಡರಲ್ಲಿ ಒಂದನ್ನು ಆಯ್ಕೆಮಾಡುತ್ತೀರಿ.'),
  (gen_random_uuid()::text, 'kn', 'bae875592e85a23c', 'ಅಧ್ಯಯನದಲ್ಲಿ ಈಗಾಗಲೇ ಉತ್ತರಗಳಿವೆ, ಆದ್ದರಿಂದ ಪ್ರಶ್ನಾವಳಿಯನ್ನು ಇನ್ನು ಬದಲಾಯಿಸಲಾಗುವುದಿಲ್ಲ. ಇನ್ನೊಂದನ್ನು ಬಳಸಲು ಹೊಸ ಅಧ್ಯಯನ ರಚಿಸಿ.'),
  (gen_random_uuid()::text, 'kn', '3b30696110490a7b', 'ಅಧಿಕೃತ, 468 ಅಧ್ಯಯನಗಳ 21,175 ಜನರೊಂದಿಗೆ'),
  (gen_random_uuid()::text, 'kn', 'e124308087e6e9c0', 'ಇದು ಏನನ್ನು ಅಳೆಯುತ್ತದೆ'),
  (gen_random_uuid()::text, 'kn', '42f77b4043940783', 'ಆಯ್ಕೆಯಿಂದ ಏನು ಬದಲಾಗುತ್ತದೆ:'),
  (gen_random_uuid()::text, 'kn', '3c3472b75b92e9b3', 'ಪ್ರಾಯೋಗಿಕ ಮತ್ತು ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟ ಎಂದರೇನು?'),
  (gen_random_uuid()::text, 'kn', '068ea3511e50f59a', 'UEQ-S ನ ಬೆಂಚ್‌ಮಾರ್ಕ್ ಎಂದರೇನು?'),
  (gen_random_uuid()::text, 'kn', 'e5b400d9a24d4f60', 'ನಕಾರಾತ್ಮಕ ಪದ ಯಾವಾಗಲೂ ಎಡಭಾಗದಲ್ಲಿರುತ್ತದೆ. ಮೊದಲ 4 ಪ್ರಾಯೋಗಿಕ ಗುಣಮಟ್ಟವನ್ನು, ಕೊನೆಯ 4 ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟವನ್ನು ಅಳೆಯುತ್ತವೆ.'),
  (gen_random_uuid()::text, 'kn', '9a4e71736bd04c92', '8 ಅಂಶಗಳು'),
  (gen_random_uuid()::text, 'kn', '6b693fdd2d2678f8', 'UEQ-S ನ 8 ಜೋಡಿಗಳು'),
  (gen_random_uuid()::text, 'kn', '38be6e60ef6b0b1c', 'ಪದಜೋಡಿಗಳು'),
  (gen_random_uuid()::text, 'kn', 'e24b06506e99c6d1', 'UEQ-S ನ ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ (XLSX)'),
  (gen_random_uuid()::text, 'kn', 'ad046c0476e87fed', 'UEQ-S ನ ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಮತ್ತು data/protocolo-ueq-s.json'),
  (gen_random_uuid()::text, 'kn', 'a714567f4023225f', 'ರಫ್ತು ಮಾಡಿದ ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್'),
  (gen_random_uuid()::text, 'kn', '85813aa17fb73bf5', 'ಪ್ರಾಯೋಗಿಕ ಎಂದರೆ ವ್ಯಕ್ತಿಗೆ ಬೇಕಾದುದನ್ನು ಮಾಡಲು ಉತ್ಪನ್ನ ನೆರವಾಗುತ್ತದೆಯೇ ಎಂಬುದು: ಅಂಶಗಳು 1 ರಿಂದ 4 (ಬೆಂಬಲ, ಸುಲಭತೆ, ದಕ್ಷತೆ ಮತ್ತು ಸ್ಪಷ್ಟತೆ). ಹೆಡೋನಿಕ್ ಎಂದರೆ ಬಳಸುವುದು ಆಹ್ಲಾದಕರ ಮತ್ತು ಆಸಕ್ತಿದಾಯಕವೇ ಎಂಬುದು: ಅಂಶಗಳು 5 ರಿಂದ 8 (ರೋಮಾಂಚಕ, ಆಸಕ್ತಿದಾಯಕ, ಸೃಜನಶೀಲ ಮತ್ತು ನವೀನ). UEQ-S ಪೂರ್ಣ UEQ ನ 6 ಮಾಪಕಗಳನ್ನು ಬೇರ್ಪಡಿಸುವುದಿಲ್ಲ.'),
  (gen_random_uuid()::text, 'kn', 'ef0e1e29b2f962d8', 'ಪೂರ್ಣವು ಹೊಂದದಿದ್ದಾಗ: ಕಡಿಮೆ ಸಮಯ, ದೀರ್ಘ ಪ್ರಶ್ನಾವಳಿಯೊಳಗೆ UEQ, ಅಥವಾ ಒಬ್ಬನೇ ವ್ಯಕ್ತಿ ಹಲವು ಉತ್ಪನ್ನಗಳನ್ನು ಸತತವಾಗಿ ಮೌಲ್ಯಮಾಪನ ಮಾಡುವುದು'),
  (gen_random_uuid()::text, 'kn', '1cca5e91e7af19e4', 'ಯಾವಾಗ ಬಳಸಬೇಕು'),
  (gen_random_uuid()::text, 'kn', '7f9e52e1d71739db', 'ಪ್ರಶ್ನಾವಳಿ'),
