  (gen_random_uuid()::text, 'kn', '773e4c885727a324', 'ಮಾಪಕವಾರು UEQ-S ಫಲಿತಾಂಶಗಳು (CSV)'),
  (gen_random_uuid()::text, 'kn', '729142a8a48c4260', 'ಅಧ್ಯಯನವು UEQ-S ಬಳಸಿದರೆ, CSV ನಲ್ಲಿ UEQ-S ಕ್ರಮದಲ್ಲಿ 8 ಕಾಲಮ್‌ಗಳಿರುತ್ತವೆ, UEQ-S ನ ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ನ Data ಹಾಳೆಯಲ್ಲಿರುವಂತೆ.'),
  (gen_random_uuid()::text, 'kn', '9cdfdcbc7651d71c', 'ಪ್ರಾಯೋಗಿಕ ಗುಣಮಟ್ಟ, ಹೆಡೋನಿಕ್ ಗುಣಮಟ್ಟ ಮತ್ತು ಒಂದು ಒಟ್ಟಾರೆ ಅಂಕ ಮಾತ್ರ'),
  (gen_random_uuid()::text, 'kn', 'b34e5952b4b2083e', 'ಉತ್ತರಿಸುವ ಸಮಯ'),
  (gen_random_uuid()::text, 'kn', 'fbdd1e04c28b7a98', 'ಪೂರ್ಣ UEQ'),
