  (gen_random_uuid()::text, 'kn', '1b445fb03d286686', 'UEQ-S, ಚಿಕ್ಕ ಆವೃತ್ತಿ'),
  (gen_random_uuid()::text, 'kn', '144bff43d73703cd', 'UEQ-S, ಚಿಕ್ಕ ಆವೃತ್ತಿ · 8 ಅಂಶಗಳು · {length} ಭಾಷೆಗಳು'),
  (gen_random_uuid()::text, 'kn', '0047e4cd8189b5b1', 'ಪ್ರತಿ ಭಾಗವಹಿಸುವಿಕೆಗೆ ಒಂದು ಸಾಲು, UEQ-S ಕ್ರಮದಲ್ಲಿ 1 ರಿಂದ 7 ರ 8 ಮೌಲ್ಯಗಳು, ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಸೇರ್ಪಡೆ ಮತ್ತು ಸಂಶಯದ ಕಾಲಮ್‌ಗಳೊಂದಿಗೆ.'),
  (gen_random_uuid()::text, 'kn', '05daef7262999aa0', 'ಪ್ರತಿ ಸಾಲಿಗೆ ಒಬ್ಬ ವ್ಯಕ್ತಿ, UEQ-S ಕ್ರಮದಲ್ಲಿ 1 ರಿಂದ 7 ರ 8 ಮೌಲ್ಯಗಳು, ಶೀರ್ಷಿಕೆ ಇಲ್ಲದೆ, UEQ-S ನ ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್‌ನ Data ಹಾಳೆಯಲ್ಲಿರುವಂತೆ. ಅರ್ಧವಿರಾಮ, ಅಲ್ಪವಿರಾಮ ಅಥವಾ ಟ್ಯಾಬ್‌ನಿಂದ ಬೇರ್ಪಡಿಸಲಾಗಿದೆ. ಗರಿಷ್ಠ 5000 ಸಾಲುಗಳು.'),
  (gen_random_uuid()::text, 'kn', '72786137971549ab', 'UEQ ಮತ್ತು UEQ-S ನಡುವಿನ ವ್ಯತ್ಯಾಸ ನೋಡಿ'),
  (gen_random_uuid()::text, 'kn', 'c9eb02e0f5cf4c07', 'ಪ್ರಾಯೋಗಿಕ, ಹೆಡೋನಿಕ್ ಮತ್ತು ಒಟ್ಟಾರೆ ಗುಣಮಟ್ಟದ n, ಸರಾಸರಿ, ಪ್ರಮಾಣಿತ ವಿಚಲನ, CI95, ಆಲ್ಫಾ ಮತ್ತು ಹಂತಗಳು, ಆವೃತ್ತಿವಾರು, ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿರುವ ಭಾಗವಹಿಸುವಿಕೆಗಳೊಂದಿಗೆ ಮಾತ್ರ.'),
  (gen_random_uuid()::text, 'kn', 'e6f8b54eeeb50370', 'ಪ್ರಾಯೋಗಿಕ, ಹೆಡೋನಿಕ್ ಮತ್ತು ಒಟ್ಟಾರೆ ಗುಣಮಟ್ಟದ n, ಸರಾಸರಿ, ಪ್ರಮಾಣಿತ ವಿಚಲನ, CI95, ಆಲ್ಫಾ ಮತ್ತು ಹಂತಗಳು, ಆವೃತ್ತಿವಾರು. ಕಚ್ಚಾ ಉತ್ತರಗಳನ್ನು UEQ ಟ್ಯಾಬ್‌ನಿಂದ ರಫ್ತು ಮಾಡಲಾಗುತ್ತದೆ.'),
